-- Q1 [Upper Airway & Conducting Zone] easy skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Upper Airway & Conducting Zone', 'A researcher tracks an inhaled oxygen molecule and notes that it only crosses into the bloodstream after reaching the tiny terminal sacs deep in the lung, never while passing through the trachea or bronchi. Which structural feature of the terminal sacs, compared with the airways leading to them, best explains why gas crosses there?', '[{"label": "A", "text": "Their wall is a single layer of flattened cells, creating a very short path for gas to cross"}, {"label": "B", "text": "Their lining is a thick layer of ciliated cells that sweep gas across the wall"}, {"label": "C", "text": "Their wall is reinforced with cartilage rings that hold the passage open for gas"}, {"label": "D", "text": "Their lining secretes abundant mucus that dissolves gas and carries it across the wall"}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is A because the terminal sacs (alveoli) are lined by a single layer of flattened (simple squamous) epithelial cells, making the wall extremely thin; this minimal thickness creates a very short diffusion path, allowing gas to move across the wall efficiently. The conducting airways (trachea and bronchi) are lined by a thicker, taller ciliated epithelium and do no gas exchange, so tracking the molecule reveals crossing only once it reaches the thin-walled sacs. (Choice A) is correct: the thin, single-cell-layer wall provides the short diffusion distance that permits gas to cross where the thicker airway walls cannot.) (Choice B) is incorrect: cilia in the airways sweep mucus and trapped debris upward, not gas across the wall; a thick ciliated layer would lengthen, not shorten, the diffusion path.) (Choice C) is incorrect: cartilage rings support and hold open the trachea and bronchi (the conducting airways), not the gas-exchange sacs, and rigid cartilage would obstruct rather than aid diffusion.) (Choice D) is incorrect: mucus in the conducting airways traps particles for clearance; it does not dissolve and ferry gas across the wall, and a thick mucus-secreting lining is a feature of the non-exchanging airways.) This question tests the skill of reasoning from a structural observation to its functional consequence for gas exchange.', 'easy', '3B', 'Organ Systems', 'biology', 2, 70)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'misconception', 'Attributes gas-exchange function to ciliated conducting-airway epithelium, confusing mucociliary clearance with diffusion' FROM q
  UNION ALL
  SELECT id, 'C', 'adjacent_fact', 'Cites a real conducting-airway feature (cartilage rings) and misapplies it to the gas-exchange surface' FROM q
  UNION ALL
  SELECT id, 'D', 'misconception', 'Treats mucus as a gas-dissolving transport medium rather than a particle-trapping clearance layer of non-exchanging airways' FROM q;

-- Q2 [pH Control & the Bicarbonate Buffer] hard skill2 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'pH Control & the Bicarbonate Buffer', 'In a systemic capillary, CO2 diffuses from the tissues into a red blood cell, where it is rapidly hydrated to carbonic acid, which dissociates into H+ and bicarbonate. A researcher adds a drug that selectively blocks the intracellular enzyme catalyzing the hydration step, while leaving all membrane transporters intact. Compared with an untreated red blood cell traversing the same capillary in the same brief transit time, the treated cell is most likely to load which of the following?', '[{"label": "A", "text": "Much more bicarbonate, because blocking the enzyme forces dissolved CO2 to be converted directly into bicarbonate by an alternative route"}, {"label": "B", "text": "Much less bicarbonate, because the uncatalyzed hydration of CO2 is too slow to reach equilibrium during the cell''s brief passage through the capillary"}, {"label": "C", "text": "The same amount of bicarbonate, because the enzyme changes only the equilibrium position of the reaction, not the amount of product formed"}, {"label": "D", "text": "Much less dissolved CO2, because the enzyme is required for CO2 to physically dissolve into the cytoplasm of the red blood cell"}]'::jsonb, 'B', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is B because the enzyme that catalyzes CO2 hydration (carbonic anhydrase) does not shift the reaction''s equilibrium; it accelerates the otherwise sluggish hydration of CO2 to carbonic acid so that near-complete conversion to bicarbonate is achieved within the fraction of a second a red blood cell spends in a systemic capillary. Blocking the enzyme leaves the uncatalyzed reaction far too slow to reach equilibrium in that brief transit, so little bicarbonate is formed and loaded. (Choice B) is correct: the enzyme''s function is purely kinetic, and without it the reaction cannot keep pace with the short capillary transit time, sharply reducing bicarbonate formation and thus the dominant form in which CO2 is carried. (Choice A) is incorrect: blocking the enzyme cannot create an alternative faster route; bicarbonate is produced only through the same hydration and dissociation sequence, so inhibition reduces rather than increases bicarbonate loading. (Choice C) is incorrect: while it is true that an enzyme does not alter the equilibrium position, the reasoning fails because the cell does not have time to reach equilibrium during its brief passage, so the rate-limiting effect of the enzyme absolutely changes how much product actually forms in vivo. (Choice D) is incorrect: dissolved CO2 enters the cytoplasm by simple physical dissolution driven by its partial-pressure gradient, a process independent of the enzyme; if anything, inhibition would leave more CO2 in the dissolved form. This question tests the skill of reasoning about how an enzyme''s kinetic role, combined with a physiological time constraint, determines the outcome of CO2 transport.', 'hard', '3B', 'Organ Systems', 'biology', 2, 100)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'misconception', 'invents a nonexistent alternative reaction pathway when the real one is blocked' FROM q
  UNION ALL
  SELECT id, 'C', 'partial_truth', 'correct enzyme-does-not-shift-equilibrium premise applied without recognizing the transit-time constraint prevents equilibrium' FROM q
  UNION ALL
  SELECT id, 'D', 'misconception', 'conflates enzyme-catalyzed hydration with physical dissolution (Henry''s law) of CO2' FROM q;

-- Q3 [Upper Airway & Conducting Zone] medium skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Upper Airway & Conducting Zone', 'A diver breathes through a long rigid snorkel tube that adds a fixed length of airway between her mouth and the open air. She keeps her tidal volume unchanged, yet over successive breaths she feels increasingly short of breath. Whenever she inhales, the first air drawn into her lungs is the air that was sitting in the tube from her previous exhalation. Adding this tube is functionally equivalent to enlarging which component of the respiratory system?', '[{"label": "A", "text": "The respiratory membrane, the thin barrier across which oxygen and carbon dioxide diffuse"}, {"label": "B", "text": "The residual volume, the air remaining in the lungs after a maximal exhalation"}, {"label": "C", "text": "The conducting airway volume, which moves air toward the lungs but where no gas transfer with the blood takes place"}, {"label": "D", "text": "The inspiratory reserve, the extra alveolar volume recruited only during forced, deep breaths"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is C because the tube adds a length of airway that air must pass through and refill on every breath but where no exchange with the blood occurs, which is exactly the role of the conducting airways. Because each inhalation must first pull in the stale air left in the tube from the previous exhalation, less of the unchanged tidal volume is fresh air that reaches functioning alveoli, which is why she grows progressively breathless.

(Choice C) is correct: The conducting zone (and the added tube) constitutes anatomic dead space — airway volume that conducts air but performs no gas exchange, so enlarging it means a smaller fraction of each tidal breath reaches functioning alveoli.

(Choice A) is incorrect: The respiratory membrane is the thin barrier in the respiratory zone where diffusion actually happens; the tube adds no such surface and by definition supports no exchange, so it cannot be an extension of this structure.

(Choice B) is incorrect: Residual volume is air trapped in the lungs after maximal exhalation; it is a lung volume, not conducting tubing, and it is unaffected by adding external tube length, so it does not explain why fresh air fails to reach alveoli.

(Choice D) is incorrect: Inspiratory reserve is extra volume within the respiratory zone recruited during deep breathing; the tube adds no alveolar surface and the tidal volume is stated to be unchanged, so recruited reserve is not what the tube extends.

This item requires translating a physical scenario into the dead-space concept, exercising scientific reasoning and problem solving.', 'medium', '3B', 'Organ Systems', 'biology', 2, 90)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'adjacent_fact', 'Names the true gas-exchange structure (respiratory membrane) that the tube is precisely NOT, baiting students who invert the conducting-vs-respiratory-zone distinction' FROM q
  UNION ALL
  SELECT id, 'B', 'misconception', 'Confuses an internal static lung volume (residual volume) with added conducting-airway dead space; both are ''air not exchanged'' but arise from unrelated mechanisms' FROM q
  UNION ALL
  SELECT id, 'D', 'adjacent_fact', 'Cites a respiratory-zone reserve volume as if the tube extends alveolar capacity, exploiting confusion between reserve volumes and dead space' FROM q;

-- Q4 [Upper Airway & Conducting Zone] medium skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Upper Airway & Conducting Zone', 'A surgeon reconstructs a section of a patient''s lower airway using a soft, pliable graft made of smooth muscle and connective tissue. During a subsequent forced inspiration, this reconstructed segment narrows sharply, while the anatomically normal airway segments above and below it remain open. Which feature of the normal segments best explains why they resist this narrowing?', '[{"label": "A", "text": "A thicker layer of airway smooth muscle actively contracts to widen their lumen during inspiration."}, {"label": "B", "text": "Beating cilia on their epithelial lining generate an outward force that props the walls apart."}, {"label": "C", "text": "A denser population of surfactant-secreting cells lowers surface tension enough to hold the walls open."}, {"label": "D", "text": "Incomplete rings of firm cartilage embedded in their walls provide a semi-rigid framework that opposes inward deformation."}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is D because during a forced inspiration the pressure surrounding the airways drops sharply, and a compliant tube with no rigid support is pulled inward and collapses, whereas the semi-rigid cartilage embedded in the walls of the normal conducting airway acts as a splint that physically resists this inward deformation and keeps the lumen patent. (Choice D) is correct: the firm but incomplete cartilaginous rings give the airway wall structural rigidity, so it does not buckle when the surrounding pressure falls below the luminal pressure during a forceful breath. (Choice A) is incorrect: airway smooth muscle contraction narrows (constricts) the lumen rather than widening it, and muscle tone cannot substitute for a rigid framework in preventing pressure-driven collapse. (Choice B) is incorrect: cilia move overlying mucus to clear debris and exert no mechanical force on the airway wall, so they cannot hold a tube open against a pressure gradient. (Choice C) is incorrect: surfactant reduces surface tension in the alveoli of the respiratory zone, not in the cartilage-supported conducting airways, and lowering surface tension does not supply the wall rigidity needed to resist collapse. The item exercises reasoning about how an anatomical structure''s physical properties determine its physiological function.', 'medium', '3B', 'Organ Systems', 'biology', 2, 75)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'reversed_relationship', 'Smooth muscle framed as dilating rather than constricting the airway' FROM q
  UNION ALL
  SELECT id, 'B', 'misconception', 'Cilia miscast as providing mechanical structural support instead of mucus clearance' FROM q
  UNION ALL
  SELECT id, 'C', 'adjacent_fact', 'Alveolar surfactant function misapplied to conducting-airway wall rigidity' FROM q;

-- Q5 [Upper Airway & Conducting Zone] medium skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Upper Airway & Conducting Zone', 'During quiet inhalation, air moves rapidly through the trachea but slows to a near-standstill by the time it reaches the terminal branches deep in the lungs, where gas exchange occurs. Which structural feature of the airway tree best accounts for this drop in the linear velocity of the air?', '[{"label": "A", "text": "The repeated branching of the airways makes the combined cross-sectional area of all the distal passages far greater than that of the trachea."}, {"label": "B", "text": "Each individual bronchiole has a wider lumen than the trachea, so air spreads out as it descends."}, {"label": "C", "text": "The combined cross-sectional area of the airways steadily decreases toward the distal branches, forcing the air to slow."}, {"label": "D", "text": "The smooth muscle lining the bronchioles contracts to actively brake the incoming air."}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is A because airflow through the airway tree obeys the continuity principle (A·v = constant): for a fixed volumetric flow, linear velocity is inversely proportional to the total cross-sectional area available. Although each successive generation of airways is individually narrower, they are enormously more numerous, so their combined (summed) cross-sectional area increases by orders of magnitude from the single trachea to the millions of distal bronchioles and alveolar ducts. Because this total area rises so steeply, the velocity of the air must fall correspondingly, slowing to near zero in the respiratory zone where diffusion, not bulk flow, moves gas.

(Choice A) is correct: the summed cross-sectional area of the many parallel distal airways vastly exceeds that of the trachea, and by continuity that larger total area drives the linear velocity down.

(Choice B) is incorrect: an individual bronchiole is far narrower than the trachea, not wider. Velocity does not fall because any single tube is bigger; it falls because the many narrow tubes together present a much larger combined area than the one trachea.

(Choice C) is incorrect: it reverses the actual geometry. The combined cross-sectional area increases—not decreases—toward the periphery. A decreasing total area would speed the air up by continuity, the opposite of what is observed.

(Choice D) is incorrect: the slowing is a passive consequence of airway geometry and the continuity relationship, not an active muscular braking action. Bronchiolar smooth muscle adjusts airway resistance and diameter but does not decelerate air by contracting against the flow.

This item requires applying the continuity principle to airway structure to explain a physiological observation, reflecting Skill 2 (scientific reasoning and problem-solving).', 'medium', '3B', 'Organ Systems', 'biology', 2, 90)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'misconception', 'Believes individual distal airways are wider than the trachea, conflating single-tube diameter with summed parallel area' FROM q
  UNION ALL
  SELECT id, 'C', 'reversed_relationship', 'Reverses the geometry, claiming total cross-sectional area decreases distally (which would speed air up, not slow it)' FROM q
  UNION ALL
  SELECT id, 'D', 'misconception', 'Attributes the passive velocity drop to active smooth-muscle braking rather than continuity/airway geometry' FROM q;

-- Q6 [Upper Airway & Conducting Zone] easy skill2 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Upper Airway & Conducting Zone', 'A patient with a permanent tracheostomy breathes through a surgical opening in the neck, so inhaled air enters the trachea directly without first passing through the nasal cavity. Compared with a person who breathes through the nose, which outcome is most likely for this patient?', '[{"label": "A", "text": "Inhaled air is more thoroughly cleared of particles before reaching the bronchi"}, {"label": "B", "text": "More airborne dust and particulate matter reaches the lower airways and lungs"}, {"label": "C", "text": "Gas exchange across the alveolar membrane becomes more efficient"}, {"label": "D", "text": "The volume of air moved with each breath is substantially reduced"}]'::jsonb, 'B', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is B because the nasal cavity is the first line of particulate filtration in the respiratory tract: coarse nasal hairs (vibrissae) trap large particles, and the mucus-coated nasal mucosa traps finer particulates as air passes over it. A tracheostomy routes air directly into the trachea, bypassing the nasal cavity entirely, so inhaled particulate matter that would normally have been filtered out at the nose instead travels deeper, allowing more dust and particles to reach the lower airways and lungs. (Choice B) is correct: removing the nasal filtration step lets a greater particle load reach the bronchi and alveoli. (Choice A) is incorrect: it reverses the relationship — bypassing the nose removes filtration, so air is less thoroughly cleared, not more. (Choice C) is incorrect: nasal filtration protects the airway from particulates but does not alter the alveolar membrane, so bypassing it does not improve (and if anything could impair) gas-exchange efficiency. (Choice D) is incorrect: a tracheostomy changes where air enters, not the mechanical volume of each breath; tidal volume is governed by respiratory muscle effort, not by nasal passage. This question requires Skill 2 (Scientific Reasoning and Problem-Solving) because the student must apply the protective filtration role of the nasal cavity to predict the consequence of bypassing it.', 'easy', '3B', 'Organ Systems', 'biology', 2, 60)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'reversed_relationship', 'Reverses the filtration relationship — claims bypassing the nose improves particle clearance' FROM q
  UNION ALL
  SELECT id, 'C', 'adjacent_fact', 'Invokes an unrelated respiratory outcome (alveolar gas-exchange efficiency) not affected by nasal filtration' FROM q
  UNION ALL
  SELECT id, 'D', 'misconception', 'Confuses air-entry route with tidal volume, which is set by respiratory-muscle effort' FROM q;

-- Q7 [Upper Airway & Conducting Zone] hard skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Upper Airway & Conducting Zone', 'A pulmonologist compares two patients. Patient 1 has an acute asthma episode in which inhaled irritants trigger contraction of the muscular walls of thousands of terminal air passages simultaneously. Patient 2 has a rigid scar ring that narrows a single 2-cm segment of the windpipe to the same minimum diameter reached by any one passage in Patient 1. Both patients show elevated airway resistance, but Patient 1''s total resistance is far greater. Which feature of the affected passages best accounts for why Patient 1''s condition raises whole-lung resistance so much more?', '[{"label": "A", "text": "The affected passages in Patient 1 are lined by cartilage rather than smooth muscle, so they collapse completely during the episode while Patient 2''s single site only partially narrows."}, {"label": "B", "text": "The affected passages in Patient 1 are arranged end-to-end in series, so narrowing each one adds its resistance to the next and the effects compound down the airway tree."}, {"label": "C", "text": "The affected passages in Patient 1 lack the cartilaginous rings that hold Patient 2''s passage partly open, and because they narrow in parallel across the entire lung, constriction of all of them together drives resistance up steeply."}, {"label": "D", "text": "The affected passages in Patient 1 are the primary site of gas exchange, so narrowing them blocks diffusion directly rather than merely impeding bulk airflow."}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is C because the passages contracting in Patient 1 are bronchioles, which have smooth muscle in their walls but no cartilage, so contraction of that smooth muscle can dramatically constrict (or close) them; critically, the many bronchioles are arranged in parallel, so when diffuse constriction narrows all of them at once, the overall airway resistance rises steeply, whereas Patient 2''s single fixed tracheal narrowing affects only one point in the airway and is limited by the trachea''s supportive cartilage. (Choice C) is correct: bronchioles lack cartilage and rely on smooth muscle tone, and their parallel arrangement means simultaneous constriction of the whole population raises total resistance far more than one isolated fixed narrowing. (Choice A) is incorrect: it reverses the tissue identity — bronchioles contain smooth muscle and lack cartilage, not the other way around; the trachea is the structure supported by cartilage, so describing bronchioles as ''lined by cartilage'' is anatomically backwards. (Choice B) is incorrect: while bronchioles do branch sequentially, the physiologically decisive point is that the enormous number of small airways function as parallel conduits; treating them as a simple in-series stack misrepresents why diffuse constriction is so damaging and would wrongly predict a single tracheal site could match it. (Choice D) is incorrect: bronchioles of the conducting zone are not the gas-exchange surface — that occurs across the alveoli — so their constriction impairs bulk airflow (ventilation), not diffusion across the membrane. This item exercises the skill of reasoning about how a structure''s tissue composition and anatomical arrangement determine its physiological function.', 'hard', '3B', 'Organ Systems', 'biology', 2, 120)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'reversed_relationship', 'Swaps the tissue identities of bronchiole vs trachea (cartilage vs smooth muscle)' FROM q
  UNION ALL
  SELECT id, 'B', 'misconception', 'Treats parallel small airways as an in-series resistance stack' FROM q
  UNION ALL
  SELECT id, 'D', 'adjacent_fact', 'Confuses conducting bronchioles with the alveolar gas-exchange surface' FROM q;

-- Q8 [Upper Airway & Conducting Zone] medium skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Upper Airway & Conducting Zone', 'Following thyroid surgery, a patient is found to have injury to a nerve that supplies the intrinsic skeletal muscles of the larynx on one side, leaving those muscles unable to contract. Which outcome is most directly expected as a result of this lesion?', '[{"label": "A", "text": "Gas exchange across the alveolar membrane slows because inspired air is no longer warmed"}, {"label": "B", "text": "Mucus and trapped particles accumulate in the trachea because ciliary beating in the airway epithelium stops"}, {"label": "C", "text": "The bronchioles constrict, sharply increasing resistance to airflow reaching the alveoli"}, {"label": "D", "text": "The affected vocal fold can no longer be properly tensioned or brought to the midline, producing a hoarse, breathy voice"}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is D because the intrinsic laryngeal muscles are skeletal muscles that tension, adduct, and abduct the vocal folds; when they cannot contract, the affected fold cannot be tightened or brought to the midline, so its vibration during phonation is impaired, yielding a hoarse, breathy voice while the glottis may remain incompletely closed. (Choice D) is correct: loss of laryngeal muscle contraction removes the ability to tension and approximate the vocal fold, directly degrading voice production. (Choice A) is incorrect: warming and humidifying inspired air occurs mainly in the nasal cavity and conducting airways and is unrelated to laryngeal muscle contraction, and impaired warming would not govern the rate of alveolar gas exchange. (Choice B) is incorrect: mucociliary clearance depends on the ciliated epithelium of the airway, not on laryngeal skeletal muscle, so a motor nerve lesion to those muscles would not halt ciliary beating. (Choice C) is incorrect: bronchiolar caliber is set by airway smooth muscle under autonomic control, not by the skeletal muscles of the larynx, so this lesion would not constrict bronchioles. The reasoning skill exercised is using a structure-function relationship to predict the physiological consequence of disrupting a specific tissue.', 'medium', '3B', 'Organ Systems', 'biology', 2, 90)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'adjacent_fact', 'Attributes a real conducting-airway function (warming inspired air) to the lesioned structure and wrongly links it to alveolar gas-exchange rate' FROM q
  UNION ALL
  SELECT id, 'B', 'adjacent_fact', 'Substitutes a different airway defense mechanism (mucociliary clearance by ciliated epithelium) that is unaffected by a skeletal-muscle motor lesion' FROM q
  UNION ALL
  SELECT id, 'C', 'misconception', 'Confuses laryngeal skeletal muscle with autonomically controlled bronchiolar smooth muscle, predicting bronchoconstriction' FROM q;

-- Q9 [Upper Airway & Conducting Zone] hard skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Upper Airway & Conducting Zone', 'A patient in respiratory distress produces a high-pitched sound during inspiration only, whereas a second patient wheezes audibly during expiration only and has to actively brace and push to empty the lungs. A clinician attributes the two patterns to obstruction at different levels of the airway tree. Which localization and mechanism best account for both patterns?', '[{"label": "A", "text": "The first patient''s obstruction is in the large upper airway and the second''s is in the small bronchioles, because collapsible small airways are held open by expanding lung tissue during inspiration but narrow as the lung recoils during expiration."}, {"label": "B", "text": "Both patients are obstructed in the small bronchioles, because these airways lack the cartilage rings needed to keep them open in either phase of breathing."}, {"label": "C", "text": "The first patient''s obstruction is in the small bronchioles and the second''s is in the large upper airway, because rigid upper-airway walls collapse only when internal pressure exceeds atmospheric pressure during a forced exhale."}, {"label": "D", "text": "Both patients are obstructed in the large upper airway, because the cartilage-supported trachea is the only site narrow enough to generate audible turbulent airflow."}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is A because the level of an airway obstruction can be inferred from which breathing phase makes it worse: a large, semi-rigid upper airway (larynx/trachea) tends to be pulled narrower by the negative pressure of inspiration, producing an inspiratory noise, whereas small, cartilage-free bronchioles are splinted open by the surrounding expanding lung parenchyma during inspiration but are compressed and narrowed as that tissue recoils and pleural pressure rises during expiration, producing an expiratory pattern that worsens with forced effort. (Choice A) is correct: it correctly pairs the inspiration-worsened noise with the large upper airway and the expiration-worsened, effort-dependent wheeze with collapsible small bronchioles, and it names the right mechanism — radial traction from surrounding lung tissue holds small airways open on inspiration and is lost on expiration. (Choice B) is incorrect: while small bronchioles do lack cartilage rings, that fact alone cannot explain two opposite phase-dependent patterns, and it wrongly assigns the inspiration-only sound to the small airways even though small-airway obstruction characteristically worsens on expiration. (Choice C) is incorrect: it reverses the correct localization; the large upper airway is not rigid enough to resist the collapsing pull of inspiratory negative pressure, and small-airway obstruction does not produce an inspiration-only sound. (Choice D) is incorrect: turbulent, audible airflow is not exclusive to the trachea, and placing both obstructions in the upper airway cannot account for one pattern being inspiratory and the other being an effort-dependent expiratory wheeze. This item exercises data-to-mechanism reasoning by requiring the test-taker to map phase-of-breathing findings onto the structural and mechanical differences between conducting-zone airways.', 'hard', '3B', 'Organ Systems', 'biology', 2, 120)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'partial_truth', 'Fixates on a single true fact (bronchioles lack cartilage) and over-generalizes it to explain both phases, ignoring phase-dependence' FROM q
  UNION ALL
  SELECT id, 'C', 'reversed_relationship', 'Swaps the two localizations and describes intrathoracic dynamic compression as if it were the mechanism for extrathoracic (upper-airway) collapse' FROM q
  UNION ALL
  SELECT id, 'D', 'partial_truth', 'Uses a true fact (trachea is cartilage-supported) to wrongly claim only the trachea can produce audible turbulence, collapsing both patterns into one site' FROM q;

-- Q10 [Alveoli & the Respiratory Membrane] medium skill2 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Alveoli & the Respiratory Membrane', 'Surfactant is a lipoprotein mixture secreted by alveolar cells onto the thin fluid layer that coats the inner surface of the alveoli, where it inserts among the molecules of that fluid film. In a healthy lung, how does the presence of surfactant most directly affect the ease with which the alveoli inflate during inspiration?', '[{"label": "A", "text": "It raises alveolar surface tension, so the alveoli inflate more easily and less muscular effort is needed to expand the lungs"}, {"label": "B", "text": "It lowers alveolar surface tension, so the alveoli inflate more easily and less muscular effort is needed to expand the lungs"}, {"label": "C", "text": "It lowers alveolar surface tension, so the alveoli resist inflation more strongly and greater muscular effort is needed to expand the lungs"}, {"label": "D", "text": "It raises alveolar surface tension, so the alveoli resist inflation more strongly and greater muscular effort is needed to expand the lungs"}]'::jsonb, 'B', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is B because surfactant interferes with the cohesive hydrogen bonding among water molecules in the alveolar fluid film, lowering surface tension; because surface tension is the inward-pulling force that opposes alveolar expansion, reducing it makes the alveoli easier to inflate (raising lung compliance, the ease of inflation) and lowers the muscular work of breathing. (Choice B) is correct: it correctly pairs lowered surface tension with easier inflation and reduced effort. (Choice A) is incorrect: surfactant lowers—not raises—surface tension, even though it correctly ends in easier inflation. (Choice C) is incorrect: it correctly states surface tension falls but wrongly claims inflation becomes harder; lowering surface tension reduces, not increases, resistance to inflation. (Choice D) is incorrect: surfactant neither raises surface tension nor makes inflation harder—this reverses both effects and instead describes what a surfactant deficiency would do. This question tests the skill of relating a molecular property (surface tension of the alveolar fluid) to a whole-organ mechanical property (lung compliance and the work of breathing).', 'medium', '3B', 'Organ Systems', 'biology', 2, 75)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'partial_truth', 'correct outcome paired with reversed mechanism (raises instead of lowers surface tension)' FROM q
  UNION ALL
  SELECT id, 'C', 'partial_truth', 'correct mechanism paired with reversed mechanical consequence (harder instead of easier to inflate)' FROM q
  UNION ALL
  SELECT id, 'D', 'reversed_relationship', 'both mechanism and consequence reversed; describes surfactant deficiency instead' FROM q;

-- Q11 [Alveoli & the Respiratory Membrane] medium skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Alveoli & the Respiratory Membrane', 'A neonatologist evaluates an infant born at 28 weeks gestation who develops rapid, labored breathing and audible grunting within hours of birth. A chest radiograph shows diffuse collapse of the tiny air sacs where gas exchange occurs, and the infant must generate unusually large inspiratory pressures to reopen them with each breath. Which deficiency most directly accounts for this pattern?', '[{"label": "A", "text": "Too few elastic connective-tissue fibers, which the air sacs rely on to recoil and empty during exhalation"}, {"label": "B", "text": "Too little mucus from the goblet cells that line the conducting passages carrying air toward the air sacs"}, {"label": "C", "text": "Too little of the fluid secreted by type II alveolar cells that keeps the moist air sacs from being pulled shut"}, {"label": "D", "text": "Too thin a respiratory membrane across which oxygen and carbon dioxide must diffuse between air and blood"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is C because the diffuse air-sac collapse and the excessive inspiratory pressure needed to reopen them are the direct consequences of a shortage of surfactant, the surface-active lipoprotein secreted by type II alveolar cells that lowers the surface tension of the thin liquid film lining the alveoli; a 28-week preterm infant has not yet made enough of it, so surface tension pulls the moist alveolar walls together (respiratory distress syndrome). (Choice C) is correct: without adequate surfactant, high surface tension at the air-liquid interface collapses the alveoli and forces much larger pressure changes to reinflate them, exactly matching the radiograph and the labored, high-effort breathing. (Choice A) is incorrect: elastic fibers drive the passive recoil of exhalation, so their loss would impair emptying and trap air rather than cause the inspiratory alveolar collapse and difficult reinflation seen here. (Choice B) is incorrect: goblet-cell mucus traps debris in the conducting airways and has no role in holding the gas-exchange alveoli open, so its deficiency would not produce diffuse alveolar collapse. (Choice D) is incorrect: a thinner respiratory membrane would speed gas diffusion rather than collapse air sacs, so it cannot explain the collapse or the increased effort to inflate them. This question exercises the skill of reasoning about how a cellular deficiency produces a specific organ-system malfunction.', 'medium', '3B', 'Organ Systems', 'biology', 2, 90)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'adjacent_fact', 'Confuses passive elastic recoil (exhalation) with surfactant''s role in keeping alveoli open on inspiration' FROM q
  UNION ALL
  SELECT id, 'B', 'misconception', 'Substitutes a conducting-airway defense (mucus) for an alveolar surface-tension function' FROM q
  UNION ALL
  SELECT id, 'D', 'reversed_relationship', 'Treats a thinner diffusion membrane as harmful when it actually speeds gas exchange' FROM q;

-- Q12 [Alveoli & the Respiratory Membrane] hard skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Alveoli & the Respiratory Membrane', 'An experimenter isolates a pair of connected air sacs of unequal radius that share a single common airway. She chemically deactivates the film of secreted lipoprotein that normally lines the inner surface of both sacs, so that the residual liquid lining exerts the same surface tension everywhere. She then seals the preparation and allows air to redistribute freely through the shared airway. Which outcome is she most likely to record?', '[{"label": "A", "text": "The larger sac progressively empties as its air passes into the smaller sac."}, {"label": "B", "text": "Both sacs settle at equal radius because the shared airway distributes pressure evenly between them."}, {"label": "C", "text": "Both sacs collapse completely because deactivating the lining raises the collapse pressure identically in each."}, {"label": "D", "text": "The smaller sac progressively empties as its air passes into the larger sac."}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is D because, once the tension-lowering lipoprotein film (surfactant) is deactivated and surface tension is uniform across the two connected sacs, the collapsing (inward) pressure of each sac depends only on its radius (Laplace''s law, P = 2T/r): the sac with the smaller radius generates the greater inward pressure, so air flows from the higher-pressure small sac through the shared airway into the lower-pressure large sac, and the small sac empties into the large one. (Choice D) is correct: with equal surface tension in both sacs, the smaller radius yields the higher collapse pressure and preferentially discharges its air into the larger, lower-pressure sac. (Choice A) is incorrect: it reverses the relationship, treating the larger sac as the higher-pressure compartment; for equal surface tension the larger radius yields the lower collapse pressure, so the large sac receives air rather than donating it. (Choice B) is incorrect: the shared airway lets air move but does not equalize the sacs, because at their differing radii the two sacs generate different collapse pressures; the connection drives net flow toward equal pressure, which is reached only after the small sac has emptied into the large one, not by the two sacs settling at equal size. (Choice C) is incorrect: deactivating the film raises the collapse tendency, but not identically, because collapse pressure depends on radius; the sacs behave unequally, and the net result is redistribution between them rather than simultaneous total collapse of both. This item exercises data-to-mechanism reasoning by requiring the student to predict physiological behavior from a described experimental manipulation.', 'hard', '3B', 'Organ Systems', 'biology', 2, 110)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'reversed_relationship', 'Inverts the Laplace radius-pressure relationship, treating the larger sac as the higher-pressure donor.' FROM q
  UNION ALL
  SELECT id, 'B', 'misconception', 'Assumes a shared airway equalizes sac size rather than driving net flow toward pressure equilibrium.' FROM q
  UNION ALL
  SELECT id, 'C', 'partial_truth', 'Correctly notes surfactant loss raises collapse tendency but wrongly treats the effect as radius-independent and identical in both sacs.' FROM q;

-- Q13 [Gas Exchange & Pulmonary Circulation] medium skill4 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Gas Exchange & Pulmonary Circulation', 'At 4,500 m elevation, the reduced atmospheric pressure lowers a climber''s alveolar PO2 to about 60 mmHg, while the PO2 of the mixed venous blood arriving at the pulmonary capillaries is still roughly 40 mmHg. Her respiratory membrane is anatomically normal in thickness and surface area. Compared with breathing at sea level (alveolar PO2 about 104 mmHg), why does oxygen move into her capillary blood more slowly at this altitude?', '[{"label": "A", "text": "The lower alveolar PO2 shrinks the alveolar-to-capillary partial-pressure difference, weakening the driving force for O2 diffusion."}, {"label": "B", "text": "The lower atmospheric pressure thickens the respiratory membrane, lengthening the distance O2 must diffuse."}, {"label": "C", "text": "The lower alveolar PO2 reduces the solubility of O2 in the alveolar fluid lining, so less O2 dissolves before crossing."}, {"label": "D", "text": "The lower atmospheric pressure reduces the total alveolar surface area available for O2 exchange."}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is A because the rate of O2 diffusion across the respiratory membrane depends on the partial-pressure gradient between alveolar air and capillary blood; at altitude the reduced atmospheric (and therefore alveolar) PO2 falls to about 60 mmHg, so the gradient driving O2 into venous blood (still ~40 mmHg) shrinks from ~64 mmHg to ~20 mmHg, slowing uptake even though the membrane itself is unchanged. (Choice A) is correct: with a normal membrane, the only variable that changed is the alveolar PO2, and a smaller alveolar-to-blood PO2 difference means a weaker driving force and slower diffusion, producing hypoxemia. (Choice B) is incorrect: atmospheric pressure does not deposit tissue or thicken the respiratory membrane; the stem specifies membrane thickness is normal, so diffusion distance is unchanged. (Choice C) is incorrect: the solubility of O2 in the fluid lining is a fixed physical property of the gas and liquid and does not fall when PO2 drops; a lower PO2 lowers the amount dissolved at equilibrium, but that reflects the gradient effect, not a change in solubility. (Choice D) is incorrect: alveolar surface area is an anatomical feature of the lung and is not reduced by lower barometric pressure; the stem states surface area is normal. This item tests the skill of reasoning about how a change in one determinant of gas diffusion—the partial-pressure gradient—alters the rate of alveolar gas exchange.', 'medium', '3B', 'Organ Systems', 'biology', 4, 90)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'misconception', 'attributes hypoxemia to a structural membrane change (thickness) rather than the driving gradient' FROM q
  UNION ALL
  SELECT id, 'C', 'misconception', 'confuses amount dissolved at equilibrium with a change in the fixed Henry''s-law solubility constant' FROM q
  UNION ALL
  SELECT id, 'D', 'misconception', 'attributes hypoxemia to reduced surface area rather than the driving gradient' FROM q;

-- Q14 [Alveoli & the Respiratory Membrane] medium skill2 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Alveoli & the Respiratory Membrane', 'After a bout of lung injury damages the flat cells that form most of the alveolar gas-exchange surface, a repopulating cell type both secretes surfactant into the alveolar lining fluid and divides to replace the lost flat cells. Which alveolar cell type performs both of these roles?', '[{"label": "A", "text": "Type I pneumocytes (squamous alveolar cells)"}, {"label": "B", "text": "Type II pneumocytes (great alveolar cells)"}, {"label": "C", "text": "Alveolar macrophages (dust cells)"}, {"label": "D", "text": "Capillary endothelial cells of the alveolar wall"}]'::jsonb, 'B', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is B because type II pneumocytes are the cuboidal alveolar cells that both synthesize and secrete surfactant, the surface-active lipoprotein lining the alveoli and act as progenitor (stem) cells that proliferate to regenerate the type I epithelium after injury. (Choice B) is correct: type II pneumocytes uniquely combine surfactant secretion with the progenitor role that restores the flat type I lining. (Choice A) is incorrect: type I pneumocytes are the thin squamous cells that form the gas-exchange surface itself, but they are terminally specialized and do not secrete surfactant or self-renew to replace themselves. (Choice C) is incorrect: alveolar macrophages are phagocytic immune cells that engulf inhaled particles and debris; they neither make surfactant nor regenerate epithelium. (Choice D) is incorrect: capillary endothelial cells line the pulmonary capillaries and form the vascular side of the respiratory membrane, playing no role in surfactant production or replacing the alveolar epithelial lining. Skill: This item tests your ability to identify the cell type responsible for specific structural and functional roles in the alveolar lining.', 'medium', '3B', 'Organ Systems', 'biology', 2, 70)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'adjacent_fact', 'Names the correct partner cell type (type I) whose function is described in the stem as the damaged cells, tempting a reader who confuses which pneumocyte does the regenerating' FROM q
  UNION ALL
  SELECT id, 'C', 'misconception', 'Cites another resident alveolar cell (macrophage) whose defensive role is conflated with epithelial repair/secretion' FROM q
  UNION ALL
  SELECT id, 'D', 'adjacent_fact', 'Names the other half of the respiratory membrane (endothelium), attractive to a reader who blurs the alveolar epithelial lining with the capillary lining' FROM q;

-- Q15 [Gas Exchange & Pulmonary Circulation] medium skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Gas Exchange & Pulmonary Circulation', 'The bronchi and their surrounding airway walls are living tissue that must be supplied with oxygen and nutrients. In a healthy person, the vessels that meet this metabolic demand deliver blood that, compared with the blood inside the pulmonary artery, is:', '[{"label": "A", "text": "Oxygen-poor blood identical to that in the pulmonary artery, because all blood entering the lung must first be oxygenated at the alveoli"}, {"label": "B", "text": "Oxygen-rich blood that has just completed gas exchange, because the airway walls are supplied by branches of the pulmonary veins returning from the alveoli"}, {"label": "C", "text": "Oxygen-rich systemic arterial blood, because these vessels branch from the aorta to nourish the airway walls rather than to participate in gas exchange"}, {"label": "D", "text": "Oxygen-poor systemic blood, because the airway walls are supplied by branches of the venae cavae that drain deoxygenated blood from the body"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is C because the airway walls are nourished by the bronchial circulation, whose bronchial arteries arise from the systemic circulation (the aorta) and therefore carry oxygen-rich systemic arterial blood; this nutritive supply is functionally distinct from the pulmonary artery, which carries oxygen-poor blood to the alveoli for gas exchange. (Choice C) is correct: bronchial arteries are systemic vessels that branch from the aorta to deliver oxygenated blood that meets the metabolic needs of the conducting airway walls, unlike the pulmonary artery''s gas-exchange role. (Choice A) is incorrect: it wrongly assumes all lung blood arrives via the pulmonary artery and must be oxygenated at the alveoli, ignoring the separate systemic bronchial supply, which is already oxygenated before reaching the airways. (Choice B) is incorrect: the pulmonary veins carry blood away from the lung toward the heart and do not branch to supply the airway walls; the nutritive supply is arterial and systemic, not a post-exchange venous branch. (Choice D) is incorrect: although it correctly identifies the supply as systemic, the venae cavae are veins returning deoxygenated blood to the heart and do not give off arterial branches to nourish tissue; the airway walls receive oxygen-rich blood from the systemic arterial (bronchial artery) circulation. This question tests the skill of distinguishing the nutritive bronchial circulation from the gas-exchange pulmonary circulation.', 'medium', '3B', 'Organ Systems', 'biology', 2, 90)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'misconception', 'Belief that all blood entering the lung arrives via the pulmonary artery and must be oxygenated at the alveoli' FROM q
  UNION ALL
  SELECT id, 'B', 'reversed_relationship', 'Confusing pulmonary veins (drainage) as the arterial supply source for airway walls' FROM q
  UNION ALL
  SELECT id, 'D', 'partial_truth', 'Correctly identifies systemic origin but assigns a venous (vena cava) source carrying deoxygenated blood' FROM q;

-- Q16 [Alveoli & the Respiratory Membrane] hard skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Alveoli & the Respiratory Membrane', 'In a lung damaged by widespread capillary destruction, so much of the pulmonary capillary bed has been eliminated that the remaining vessels must carry the entire cardiac output. As a result, each red blood cell now spends only about a quarter of the normal time passing an alveolus. Assuming alveolar PO2 and membrane thickness are unchanged, which explanation best accounts for why blood leaving these alveoli is still incompletely oxygenated?', '[{"label": "A", "text": "The reduced capillary bed lowers the alveolar-to-capillary PO2 gradient, so the driving force for diffusion is too small to load oxygen."}, {"label": "B", "text": "The faster-moving red blood cells generate turbulent flow that physically blocks oxygen from crossing the respiratory membrane."}, {"label": "C", "text": "The loss of capillaries thickens the respiratory membrane, increasing the diffusion distance that oxygen must travel."}, {"label": "D", "text": "The shortened contact time no longer allows capillary PO2 to rise all the way to alveolar PO2 before the cell exits the exchange region."}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is D because oxygen loading depends not only on an adequate partial-pressure gradient but also on the red blood cell spending enough time in the capillary for its PO2 to equilibrate with alveolar air; when destruction of the capillary bed forces the whole cardiac output through fewer vessels, each cell traverses the exchange region far faster, and if transit time falls below the time required to reach equilibrium, the cell exits still incompletely oxygenated despite a normal gradient and normal membrane. (Choice D) is correct: it correctly identifies that inadequate contact (transit) time, not an inadequate gradient or barrier, prevents capillary PO2 from reaching alveolar PO2. (Choice A) is incorrect: the alveolar PO2 is stated to be unchanged and capillary blood arrives at its usual low PO2, so the driving gradient is intact—the problem is the time available to act on that gradient, not the gradient itself. (Choice B) is incorrect: pulmonary capillary flow remains laminar at these velocities, and turbulence does not form a barrier to diffusion; oxygen crosses the membrane by dissolving and diffusing down its partial-pressure gradient regardless of flow character. (Choice C) is incorrect: the stem specifies that membrane thickness is unchanged, and losing capillaries does not deposit tissue that lengthens the diffusion path—this describes a distance-limited defect rather than the transit-time defect actually at work. This item tests the skill of reasoning about how perfusion dynamics and equilibration kinetics, not just the diffusion gradient, determine the completeness of alveolar gas exchange.', 'hard', '3B', 'Organ Systems', 'biology', 2, 110)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'reversed_relationship', 'Attributes the failure to a shrunken PO2 gradient when the stem fixes the gradient as normal; confuses driving force with time available to act on it' FROM q
  UNION ALL
  SELECT id, 'B', 'misconception', 'Invokes turbulence as a physical barrier to diffusion, a plausible-sounding but false flow-mechanics mechanism for gas transfer' FROM q
  UNION ALL
  SELECT id, 'C', 'process_step_confusion', 'Substitutes a thickened-membrane (distance-limited) defect for the transit-time defect, contradicting the stem''s fixed membrane thickness' FROM q;

-- Q17 [Alveoli & the Respiratory Membrane] medium skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Alveoli & the Respiratory Membrane', 'A researcher compares two regions of a patient''s lung. In a healthy region, oxygen crosses from the air space into the blood across a barrier only two cells thick. In a fibrotic region, deposited connective tissue has thickened this barrier several-fold, while total alveolar surface area and the partial-pressure difference across the barrier remain unchanged. Compared with the healthy region, oxygen movement into the capillary blood of the fibrotic region is most likely:', '[{"label": "A", "text": "Slower, because the greater distance the gas must traverse impedes diffusion"}, {"label": "B", "text": "Faster, because the added tissue increases the surface available for exchange"}, {"label": "C", "text": "Unchanged, because the partial-pressure difference is the sole determinant of exchange"}, {"label": "D", "text": "Slower, because the thicker barrier reduces the pressure gradient driving the gas"}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is A because gas exchange at the respiratory membrane occurs by simple diffusion, and the rate of diffusion falls as the distance molecules must travel rises; thickening the barrier lengthens the diffusion path and slows oxygen movement even when surface area and the partial-pressure difference are held constant. (Choice A) is correct: the normally minimal ~two-cell thickness of the respiratory membrane keeps the diffusion distance short, so multiplying that thickness with fibrotic tissue lengthens the path and reduces the diffusion rate. (Choice B) is incorrect: the deposited connective tissue thickens the barrier rather than expanding gas-exchange surface, and the stem explicitly holds surface area constant, so no area-based speedup occurs. (Choice C) is incorrect: while the partial-pressure difference is one driver of diffusion, it is not the only one—diffusion distance also matters—so an unchanged gradient does not keep the rate constant when the barrier thickens. (Choice D) is incorrect: adding tissue thickness does not lower the partial-pressure difference across the membrane, which the stem fixes; it lengthens the path the gas must cross, and that longer path—not any change in the gradient—is the actual cause of the slowdown. This item exercises applying a diffusion principle (rate varies inversely with distance) to predict a physiological outcome from a described scenario.', 'medium', '3B', 'Organ Systems', 'biology', 2, 90)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'misconception', 'Misattributes added tissue to increased exchange surface area, inverting the actual effect' FROM q
  UNION ALL
  SELECT id, 'C', 'partial_truth', 'Treats the partial-pressure gradient as the sole determinant, ignoring diffusion distance' FROM q
  UNION ALL
  SELECT id, 'D', 'reversed_relationship', 'Right direction (slower) via wrong mechanism—confuses path length with the driving pressure gradient' FROM q;

-- Q18 [Alveoli & the Respiratory Membrane] hard skill2 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Alveoli & the Respiratory Membrane', 'Two patients each show impaired oxygen movement across the respiratory membrane. In Patient 1, high-resolution imaging reveals that many alveolar walls have broken down, merging neighboring air sacs into fewer, larger chambers, while the remaining walls appear normally thin. In Patient 2, the alveolar walls remain intact and numerous, but a dense protein-rich layer has been deposited within the interstitial space between the alveolar epithelium and the capillary endothelium. Which conclusion about the primary diffusion defect in each patient is best supported?', '[{"label": "A", "text": "Both patients have an increased diffusion distance, since wall breakdown in Patient 1 also lengthens the path gas must travel."}, {"label": "B", "text": "Patient 1''s defect stems from reduced gas-exchange surface area, whereas Patient 2''s stems from an increased diffusion distance across the membrane."}, {"label": "C", "text": "Patient 1''s defect stems from an increased diffusion distance, whereas Patient 2''s stems from reduced surface area caused by protein blocking the alveoli."}, {"label": "D", "text": "Both patients have reduced surface area, since the interstitial deposit in Patient 2 collapses alveoli and eliminates their exchange area."}]'::jsonb, 'B', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is B because the rate of gas diffusion across the respiratory membrane rises with the total surface area available and falls as the distance gas must travel increases; the two lesions described map cleanly onto these two separate variables. In Patient 1, destruction of alveolar walls fuses many small sacs into fewer large ones, which shrinks the aggregate internal surface area while leaving the remaining membrane thin — a surface-area problem. In Patient 2, the walls and sac count are preserved, but a new protein-rich layer inserted between the alveolar epithelium and capillary endothelium physically widens the barrier gas must cross — a diffusion-distance problem. (Choice B) is correct: it correctly assigns the loss of alveolar walls (fewer, larger sacs) to reduced surface area and the interstitial deposit (a thicker interposed barrier) to increased diffusion distance. (Choice A) is incorrect: merging alveoli into larger chambers does not thicken the membrane — the remaining walls are explicitly still thin — so Patient 1''s defect is surface area, not distance; the claim conflates a bigger chamber with a longer diffusion path. (Choice C) is incorrect: it reverses both assignments — Patient 1 lost walls (surface area) rather than gaining barrier thickness, and Patient 2''s deposit thickens the membrane rather than plugging air sacs to remove surface area. (Choice D) is incorrect: nothing in Patient 2 collapses alveoli or removes their walls; the sacs remain intact and numerous, so surface area is preserved and the defect is the widened barrier, meaning the two patients do not share the same mechanism. The reasoning skill exercised is applying the determinants of membrane gas diffusion to distinguish two mechanisms from structural data (AAMC Skill 2: Scientific Reasoning and Problem-Solving).', 'hard', '3B', 'Organ Systems', 'biology', 2, 110)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'misconception', 'Conflates a larger alveolar chamber with a longer diffusion path, treating loss of surface area as an increase in membrane thickness' FROM q
  UNION ALL
  SELECT id, 'C', 'reversed_relationship', 'Swaps the two mechanisms, assigning diffusion distance to the wall-loss patient and surface area to the interstitial-deposit patient' FROM q
  UNION ALL
  SELECT id, 'D', 'partial_truth', 'Overextends the interstitial deposit into alveolar collapse to force both patients into a single reduced-surface-area mechanism' FROM q;

-- Q19 [Airway Resistance & Airflow] medium skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Airway Resistance & Airflow', 'During an acute asthma attack, smooth muscle constriction reduces the radius of a bronchiole to exactly one-half of its resting value. If the driving pressure across the airway is unchanged, by approximately what factor does the resistance to airflow through that bronchiole increase, given that resistance is inversely proportional to the fourth power of the radius?', '[{"label": "A", "text": "About 4-fold"}, {"label": "B", "text": "About 8-fold"}, {"label": "C", "text": "About 16-fold"}, {"label": "D", "text": "About 2-fold"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is C because resistance to airflow is inversely proportional to the fourth power of the radius (R ∝ 1/r⁴), so halving the radius multiplies the resistance by (1/(1/2))⁴ = 2⁴ = 16.

(Choice A) is incorrect: A 4-fold increase would follow if resistance scaled as 1/r² (as cross-sectional area does), but the fourth-power dependence is specified here, not the second, so this underestimates the true effect.

(Choice B) is incorrect: An 8-fold increase corresponds to 2³, mistakenly using the third power of the radius; the relationship is 1/r⁴, giving 2⁴ = 16, not 2³ = 8.

(Choice C) is correct: Halving the radius makes 1/r⁴ change by a factor of 2⁴ = 16. Because resistance depends so steeply on radius, even a modest narrowing produces a large rise in resistance, which is why bronchoconstriction so dramatically impairs airflow at a fixed driving pressure.

(Choice D) is incorrect: A 2-fold increase would result if resistance were simply inversely proportional to the radius (1/r¹); the fourth-power dependence makes the actual increase far larger (2⁴ = 16).

This item tests the skill of applying the fourth-power radius dependence of airway resistance to quantitatively relate a change in bronchiole radius to the resulting change in resistance to airflow.', 'medium', '3B', 'Organ Systems', 'biology', 2, 75)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'scale_unit_error', 'Applies squared (area) scaling instead of fourth-power, yielding 2² = 4' FROM q
  UNION ALL
  SELECT id, 'B', 'scale_unit_error', 'Uses third-power exponent, yielding 2³ = 8' FROM q
  UNION ALL
  SELECT id, 'D', 'scale_unit_error', 'Uses linear (first-power) inverse dependence, yielding 2¹ = 2' FROM q;

-- Q20 [Pleurae & the Thoracic Cavity] hard skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Pleurae & the Thoracic Cavity', 'A patient with pulmonary fibrosis has lungs that are abnormally stiff, so a given rise in transpulmonary pressure inflates them less than it would a healthy lung. To draw in her usual resting tidal volume of 0.5 L, how must the change in intrapleural pressure during inspiration compare with that of a healthy person breathing the same tidal volume, and why?', '[{"label": "A", "text": "She must make her intrapleural pressure fall by a smaller amount, because a stiffer lung requires a greater transpulmonary pressure to expand by each unit of volume."}, {"label": "B", "text": "She must make her intrapleural pressure fall by a larger amount, because a stiffer lung has increased compliance and therefore expands more readily per unit of pressure."}, {"label": "C", "text": "She can use the same fall in intrapleural pressure, because tidal volume, not lung stiffness, sets the pressure change needed for inspiration."}, {"label": "D", "text": "She must make her intrapleural pressure fall by a larger amount, because a stiffer lung requires a greater transpulmonary pressure to expand by each unit of volume."}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is D because compliance is the change in lung volume produced per unit change in transpulmonary (distending) pressure; a fibrotic lung has low compliance, so a larger transpulmonary pressure change is needed to add each unit of volume, and since alveolar pressure returns to near-atmospheric while air flows, that larger transpulmonary pressure must come from a larger (more negative) drop in intrapleural pressure to achieve the same 0.5 L tidal volume. (Choice D) is correct: it correctly pairs the larger intrapleural pressure drop with the mechanism that a stiffer, low-compliance lung requires more transpulmonary pressure per unit volume. (Choice A) is incorrect: although its stated mechanism—that a stiffer lung needs a greater transpulmonary pressure—is accurate, the magnitude claim is reversed, because a stiffer lung requires a larger, not smaller, intrapleural pressure change. (Choice B) is incorrect: it gives the right direction (larger pressure drop) but misstates the mechanism, because a stiff fibrotic lung has decreased, not increased, compliance and expands less readily, not more readily, per unit pressure. (Choice C) is incorrect: the pressure change needed depends on both the target volume and the lung''s compliance, so at equal tidal volume the low-compliance lung still demands a larger intrapleural pressure change. This question tests the skill of reasoning from the compliance relationship (ΔV per ΔP) to predict how altered lung stiffness changes the intrapleural pressure required for a fixed tidal volume.', 'hard', '3B', 'Organ Systems', 'biology', 2, 110)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'reversed_relationship', 'Correct mechanism paired with reversed magnitude/direction of the intrapleural pressure change' FROM q
  UNION ALL
