  SELECT id, 'B', 'process_step_confusion', 'Reports the intermediate volume flow rate (A·v) as if it were the final velocity, omitting the final division by A₂' FROM q
  UNION ALL
  SELECT id, 'C', 'scale_unit_error', 'Divides by the trachea''s own area value (~2.5) instead of by the full area ratio (~400), underestimating the slowdown' FROM q
  UNION ALL
  SELECT id, 'D', 'reversed_relationship', 'Multiplies by the area ratio instead of dividing, reversing the inverse A·v relationship so velocity rises as area widens' FROM q;

-- Q22 [Pleurae & the Thoracic Cavity] easy skill2 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Pleurae & the Thoracic Cavity', 'A surgeon repairing an abdominal injury inadvertently creates an opening through the sheet of skeletal muscle that forms the floor of the thoracic cavity, allowing a loop of intestine to protrude upward toward the lungs. Which functional problem most directly results from this defect?', '[{"label": "A", "text": "The lungs lose the serous fluid layer that lets them slide against the chest wall"}, {"label": "B", "text": "Contraction of the muscle can no longer expand the volume of the chest during inhalation as effectively"}, {"label": "C", "text": "Air can no longer travel from the trachea into the bronchi during breathing"}, {"label": "D", "text": "The airways lose the smooth muscle that adjusts their diameter during airflow"}]'::jsonb, 'B', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is B because the muscular sheet forming the floor of the thoracic cavity is the diaphragm, and its downward contraction increases thoracic volume to drive inhalation; a hole in it that lets abdominal contents push upward compromises its ability to flatten and enlarge the chest. (Choice B) is correct: the diaphragm is the primary muscle of inspiration, and a breach that permits intestine to herniate into the thorax disrupts the intact, dome-shaped sheet needed to expand thoracic volume when it contracts. (Choice A) is incorrect: the slippery fluid layer between the lungs and chest wall is produced by the pleural membranes, not the diaphragm, so a diaphragmatic defect does not remove it. (Choice C) is incorrect: airflow from the trachea into the bronchi depends on the patent conducting airways, which are anatomically separate from the diaphragm and remain open despite the defect. (Choice D) is incorrect: the smooth muscle that changes airway diameter lies in the walls of the bronchi and bronchioles, not in the diaphragm, so it is unaffected by a hole in the muscular floor of the thorax. This item exercises the skill of applying a foundational concept about the diaphragm''s anatomical position to predict the physiological consequence of a structural defect.', 'easy', '3B', 'Organ Systems', 'biology', 2, 75)
  RETURNING id
)
