-- Q24 [Pleurae & the Thoracic Cavity] hard skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Pleurae & the Thoracic Cavity', 'During a maximal inspiratory effort, an athlete''s accessory neck muscles raise the rib cage far more than during quiet breathing. A moment later, a sharp object pierces the right chest wall, creating a small opening that connects the right pleural space to the surrounding air. Compared with quiet breathing, how does the right lung behave during the maximal effort, and how does it behave immediately after the chest wall is opened?', '[{"label": "A", "text": "During the effort it expands less than in quiet breathing; after the chest wall is opened it expands further outward."}, {"label": "B", "text": "During the effort it expands more than in quiet breathing; after the chest wall is opened it expands further outward."}, {"label": "C", "text": "During the effort it stays about the same as in quiet breathing; after the chest wall is opened it partially collapses inward."}, {"label": "D", "text": "During the effort it expands more than in quiet breathing; after the chest wall is opened it partially collapses inward."}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is D because the size of the lung is set by the transpulmonary pressure — the difference between intra-alveolar pressure and intrapleural pressure. A maximal effort that lifts the rib cage further than quiet breathing pulls the chest wall outward and makes intrapleural pressure more negative, widening the transpulmonary difference and expanding the lung more; opening the chest wall lets outside air enter the pleural space, so intrapleural pressure rises toward atmospheric, the transpulmonary difference collapses, and the lung''s own elastic recoil draws it partially inward. (Choice D) is correct: greater rib-cage elevation deepens the negative intrapleural pressure and increases expansion, while the breach equalizes intrapleural pressure with the atmosphere and lets elastic recoil pull the lung inward. (Choice A) is incorrect: it reverses the effort effect — a larger inspiratory effort increases, not decreases, expansion — and it wrongly claims the lung expands outward after the breach, when losing the negative pleural gradient instead causes collapse. (Choice B) is incorrect: the first clause is right, but a breach cannot drive the lung to expand further outward; admitting air to the pleural space does not push the lung open, and without a negative intrapleural pressure holding it against the chest wall, elastic recoil dominates and the lung recedes. (Choice C) is incorrect: raising the rib cage beyond the quiet-breathing level must increase expansion rather than leave lung volume unchanged, even though it correctly recognizes that the breach causes inward collapse. This item exercises reasoning about the mechanical basis of a living system by predicting lung volume changes from shifts in the intrapleural pressure gradient across two conditions.', 'hard', '3B', 'Organ Systems', 'biology', 2, 120)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'reversed_relationship', 'Inverts both mechanisms — treats greater effort as reducing expansion and treats pleural air as inflating the lung' FROM q
  UNION ALL
  SELECT id, 'B', 'partial_truth', 'Correct effort clause paired with the misconception that air entering the pleural space pushes the lung outward (open pneumothorax confused with positive-pressure inflation)' FROM q
  UNION ALL
  SELECT id, 'C', 'misconception', 'Assumes accessory muscles merely maintain rather than augment expansion, so volume is unchanged; pairs it with the correct collapse outcome' FROM q;

-- Q25 [Pleurae & the Thoracic Cavity] hard skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Pleurae & the Thoracic Cavity', 'During a thoracostomy, a surgeon inadvertently perforates the outer membrane lining the chest wall, opening a small channel between the space surrounding one lung and the outside atmosphere. Immediately, that lung collapses toward its hilum while the chest wall springs slightly outward, even though the airway itself remains open and unobstructed. Which change best accounts for why the lung no longer stays expanded against the thoracic wall?', '[{"label": "A", "text": "The pressure in the space surrounding the lung rose to equal the pressure inside the alveoli, so the outward-pulling gradient that had opposed elastic recoil disappeared."}, {"label": "B", "text": "The fluid layer between the two membranes was lost, removing the surface-tension cohesion that had physically glued the lung to the chest wall."}, {"label": "C", "text": "Atmospheric air raised alveolar pressure above the pressure in the surrounding space, actively pushing the lung inward toward its hilum."}, {"label": "D", "text": "The elastic fibers of the lung suddenly gained tension because the chest wall stopped stretching them outward against their recoil."}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is A because the lung is normally held expanded not by any glue but by a pressure difference: the intrapleural space is subatmospheric, so the pressure across the lung wall (alveolar minus intrapleural, the transpulmonary pressure) is positive and holds the lung distended against its own inward elastic recoil; puncturing the parietal membrane lets air enter until intrapleural pressure rises to atmospheric — the same as alveolar pressure — collapsing that transpulmonary gradient to zero and letting the unopposed recoil pull the lung inward while the freed chest wall springs out. (Choice A) is correct: equalizing intrapleural and alveolar pressure abolishes the positive transpulmonary pressure, so nothing counters the lung''s elastic recoil and it collapses. (Choice B) is incorrect: although a thin serous film does provide cohesion and couples the two pleurae, the film is not a rigid glue holding the lung open against recoil; the decisive factor is the loss of the subatmospheric pressure gradient, not evaporation of fluid, and pleural fluid is not simply expelled through a small air channel. (Choice C) is incorrect: with the airway open, alveolar pressure equilibrates with the atmosphere and does not exceed the newly atmospheric intrapleural pressure, so no net inward push is generated across the lung wall — the collapse is driven by the lung''s own recoil, not by air pressing it in. (Choice D) is incorrect: the lung''s elastic fibers were already under recoil tension before the injury and were being held stretched by the transpulmonary gradient; the fibers do not gain new tension, they simply act unopposed once that gradient vanishes. This item exercises the skill of reasoning about how disrupting a physiological pressure relationship changes a system''s mechanical behavior.', 'hard', '3B', 'Organ Systems', 'biology', 2, 120)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
