  SELECT id, 'A', 'reversed_relationship', 'Assigns the active/muscular role to exhalation and invokes abdominal muscles that belong to forced (not quiet) exhalation' FROM q
  UNION ALL
  SELECT id, 'B', 'misconception', 'Assumes inhalation and exhalation are mechanically symmetric, both requiring equal active contraction' FROM q
  UNION ALL
