-- Q28 [Inhalation Mechanics] medium skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Inhalation Mechanics', 'During a quiet inspiration, the diaphragm contracts and its dome descends toward the abdomen, which is filled largely with incompressible organs and fluid. A single diaphragmatic contraction therefore acts on two adjacent compartments at once: the thoracic cavity above the dome and the abdominal cavity below it. Compared with the direction of the pressure change occurring in the thoracic cavity during this movement, the direction of the pressure change registered in the abdominal cavity is best described as:', '[{"label": "A", "text": "the same in direction — both cavities enlarge as the dome descends, so pressure falls in the abdomen just as it does in the thorax"}, {"label": "B", "text": "opposite in direction — abdominal pressure falls because the descending dome pulls the abdominal wall inward and enlarges the abdominal space, whereas thoracic pressure rises"}, {"label": "C", "text": "unchanged — because the abdominal organs are incompressible, the descending dome cannot alter the pressure surrounding them"}, {"label": "D", "text": "opposite in direction — abdominal pressure rises as the descending dome compresses the nearly incompressible abdominal contents into a smaller vertical space, whereas thoracic pressure falls as that cavity enlarges"}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is D because as the diaphragm contracts, its dome descends and pushes down on the abdominal cavity, whose contents (organs and fluid) are essentially incompressible; forcing these contents into a smaller vertical space raises the pressure in the abdominal compartment. This is the mirror image of the thoracic cavity, which enlarges during the same contraction so that its internal pressure falls (drawing air inward). (Choice D) is correct: the two adjacent cavities respond in opposite directions during the single downward stroke of the dome — thoracic volume increases and its pressure drops, while the abdominal compartment is compressed and its pressure rises. (Choice A) is incorrect: the abdomen does not enlarge when the dome descends; the descending muscle reduces the space available to the abdominal contents rather than expanding it, so abdominal pressure rises rather than falls, and the two compartments are not the same in direction. (Choice B) is incorrect: the descending dome pushes down on and displaces the abdominal contents (often bulging the abdominal wall outward), it does not pull the wall inward or enlarge the space, so abdominal pressure rises, not falls; it also misstates the thoracic change as a rise. (Choice C) is incorrect: incompressibility is precisely why the pressure rises — because the contents cannot be squeezed into a smaller volume, the force of the descending dome is transmitted through them as an increase in pressure rather than absorbed as a change in their volume. This question tests the skill of reasoning about how a single muscular movement produces opposite pressure changes in two adjacent body compartments.', 'medium', '3B', 'Organ Systems', 'biology', 2, 90)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'misconception', 'Assumes both compartments behave identically (both enlarge) rather than recognizing the dome partitions them oppositely' FROM q
