-- Q43 [Lung Volumes & Capacities] easy skill1 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Lung Volumes & Capacities', 'A healthy adult sits quietly at rest and breathes normally, without any conscious effort. During each cycle, a certain amount of air moves into the lungs on inhalation and the same amount leaves on exhalation. Which lung parameter describes the amount of air moved in one of these ordinary breaths?', '[{"label": "A", "text": "Inspiratory reserve volume"}, {"label": "B", "text": "Expiratory reserve volume"}, {"label": "C", "text": "Tidal volume"}, {"label": "D", "text": "Vital capacity"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is C because the air moved in and out during a single quiet, effortless breath at rest is exactly the parameter that describes an ordinary resting breath, distinguishing it from the extra air that can be forcibly added on top of a normal breath or maximally expelled. (Choice C) is correct: tidal volume is defined as the volume of air moved into or out of the lungs during one normal, unforced breath, which is precisely the scenario described. (Choice A) is incorrect: the inspiratory reserve volume is the ADDITIONAL air that can be forcibly inhaled beyond the top of a normal breath, not the air of the normal breath itself. (Choice B) is incorrect: the expiratory reserve volume is the additional air that can be forcibly exhaled beyond the end of a normal breath, not the ordinary breath''s volume. (Choice D) is incorrect: the vital capacity is the total air moved from a maximal inhalation to a maximal exhalation, far larger than a single resting breath. Skill: This item tests recall and identification of a foundational respiratory definition from a described scenario.', 'easy', '3B', 'Organ Systems', 'biology', 1, 50)
  RETURNING id
)
