-- Q45 [Lung Volumes & Capacities] medium skill4 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Lung Volumes & Capacities', 'During pulmonary function testing, a healthy adult produces the following measurements: the volume of air moved in and out during quiet, effortless breathing is 0.5 L; the additional volume that can be forcefully inhaled beyond a quiet breath is 3.0 L; the additional volume that can be forcefully exhaled beyond a quiet breath is 1.1 L; and the volume remaining in the lungs after a maximal forced exhalation is 1.2 L. What is the maximum volume of air this individual can exhale immediately following a maximal inhalation?', '[{"label": "A", "text": "4.6 L"}, {"label": "B", "text": "3.5 L"}, {"label": "C", "text": "5.8 L"}, {"label": "D", "text": "1.7 L"}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is A because the maximum volume that can be exhaled after a maximal inhalation is the sum of the volume of a normal breath (0.5 L), the additional volume that can be forcefully inhaled (3.0 L), and the additional volume that can be forcefully exhaled (1.1 L), giving 0.5 + 3.0 + 1.1 = 4.6 L. The 1.2 L remaining after a maximal exhalation can never be expelled and is therefore excluded. (Choice B) is incorrect: 3.5 L sums only the additional forceful inhalation (3.0 L) and the normal breath (0.5 L), omitting the 1.1 L of additional forceful exhalation that is also expelled during a maximal exhalation. (Choice A) is correct: adding the normal breath, the additional forceful inhalation, and the additional forceful exhalation (0.5 + 3.0 + 1.1) yields the maximal exhalable volume of 4.6 L. (Choice C) is incorrect: 5.8 L adds all four measured volumes (0.5 + 3.0 + 1.1 + 1.2), which is the total lung capacity; it wrongly includes the 1.2 L that remains after a maximal exhalation and by definition cannot be exhaled. (Choice D) is incorrect: 1.7 L sums only the normal breath (0.5 L) and the additional forceful exhalation (1.1 L), omitting the large additional forceful inhalation (3.0 L) that a maximal inhalation adds before exhalation begins. This item requires selecting and combining the correct data values while recognizing which volume must be excluded (Skill: reasoning about the design and execution of research / data-based quantitative analysis).', 'medium', '3B', 'Organ Systems', 'biology', 4, 90)
  RETURNING id
)
