-- Q49 [Lung Volumes & Capacities] medium skill4 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Lung Volumes & Capacities', 'A healthy adult breathes quietly with a tidal volume of 500 mL at a rate of 12 breaths per minute. Of each tidal breath, 150 mL never reaches the alveoli and remains in the conducting airways, taking no part in gas exchange. What is this person''s alveolar ventilation, the volume of fresh air reaching the gas-exchange surfaces each minute?', '[{"label": "A", "text": "4,200 mL/min"}, {"label": "B", "text": "6,000 mL/min"}, {"label": "C", "text": "1,800 mL/min"}, {"label": "D", "text": "7,800 mL/min"}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is A because alveolar ventilation equals the fresh air reaching the alveoli per minute, computed as (tidal volume − anatomic dead space) × respiratory rate = (500 mL − 150 mL) × 12 = 350 mL × 12 = 4,200 mL/min. Only the portion of each breath beyond the dead-space volume participates in gas exchange. (Choice A) is correct: subtracting the 150 mL of dead space from the 500 mL tidal volume yields 350 mL of fresh air per breath, and multiplying by 12 breaths/min gives 4,200 mL/min. (Choice B) is incorrect: 6,000 mL/min is the total minute ventilation (500 mL × 12), which ignores the dead-space air that never reaches the alveoli and therefore overstates the effective ventilation. (Choice C) is incorrect: 1,800 mL/min results from multiplying the dead-space volume (150 mL) by the rate (12), which computes the wasted ventilation of the conducting airways rather than the alveolar ventilation. (Choice D) is incorrect: 7,800 mL/min results from erroneously adding the dead-space volume to the tidal volume before multiplying ((500 + 150) × 12), reversing the required subtraction. This item tests the skill of quantitatively applying the alveolar ventilation relationship, distinguishing effective gas-exchange ventilation from total minute ventilation.', 'medium', '3B', 'Organ Systems', 'biology', 4, 75)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'partial_truth', 'Computes total minute ventilation, ignoring dead space' FROM q
  UNION ALL
