-- Q54 [Neural Control of Breathing] easy skill2 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Neural Control of Breathing', 'A patient sustains isolated damage to a discrete region of the brainstem. Afterward, the patient remains awake and can answer questions in writing, but no longer generates an involuntary breathing rhythm and must be maintained on a mechanical ventilator. Loss of which structure best accounts for this pattern?', '[{"label": "A", "text": "The cerebral cortex"}, {"label": "B", "text": "The medulla oblongata"}, {"label": "C", "text": "The cerebellum"}, {"label": "D", "text": "The hypothalamus"}]'::jsonb, 'B', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is B because the automatic, rhythmic drive that sustains involuntary breathing originates in respiratory centers of the medulla oblongata; destroying this region abolishes the spontaneous breathing rhythm (requiring a ventilator) while leaving higher regions that support wakefulness and thought intact. (Choice B) is correct: the medullary respiratory center sets the intrinsic breathing rhythm and responds to CO2/H+, so its loss stops involuntary breathing yet spares consciousness, matching the described pattern. (Choice A) is incorrect: the cerebral cortex mediates voluntary (conscious) control of breathing, such as breath-holding, not the automatic rhythm; moreover the patient is still awake and communicating, so cortical function is preserved. (Choice C) is incorrect: the cerebellum coordinates movement and balance and is not the generator of the respiratory rhythm, so its loss would not selectively abolish automatic breathing. (Choice D) is incorrect: the hypothalamus governs homeostatic functions like temperature, hunger, and endocrine control, not the moment-to-moment rhythmic drive of ventilation. Skill: This item requires applying knowledge of nervous-system organization to predict the physiological consequence of losing a specific brain region.', 'easy', '3B', 'Organ Systems', 'biology', 2, 60)
  RETURNING id
)
