-- Q58 [Neural Control of Breathing] medium skill2 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Neural Control of Breathing', 'During moderate exercise, a healthy runner''s medullary respiratory center increases the frequency of its rhythmic bursts to the diaphragm and also increases the strength of each burst. Compared with rest, which change in the runner''s breathing pattern most directly results from the increased burst strength, as distinct from the increased burst frequency?', '[{"label": "A", "text": "A higher number of breaths per minute, because each burst triggers one additional inspiration"}, {"label": "B", "text": "A larger tidal volume, because stronger inspiratory muscle contractions expand the thoracic cavity more per breath"}, {"label": "C", "text": "A larger residual volume, because stronger contractions trap more air behind closed airways after each breath"}, {"label": "D", "text": "A larger anatomical dead space, because stronger contractions widen the conducting airways during inspiration"}]'::jsonb, 'B', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is B because the medullary center modulates ventilation along two independent axes: the frequency of its rhythmic bursts sets the breathing rate, while the strength of each burst sets how forcefully the inspiratory muscles contract; stronger contractions expand the thoracic cavity more, drawing in a larger tidal volume per breath. (Choice B) is correct: increased burst strength drives more forceful diaphragm and external intercostal contraction, enlarging the thoracic cavity further per breath and raising tidal volume, which is the depth axis of ventilation distinct from rate. (Choice A) is incorrect: the number of breaths per minute is set by how often the center fires (burst frequency), not by burst strength, so this describes the rate axis rather than the depth change produced by stronger bursts. (Choice C) is incorrect: residual volume is the air that cannot be exhaled after a maximal expiration and is a fixed anatomical parameter not increased by stronger inspiratory contractions; exercise increases the volume actively moved, not trapped air. (Choice D) is incorrect: anatomical dead space is the fixed volume of the conducting airways and is not meaningfully enlarged by stronger inspiratory effort; deeper breathing actually improves the ratio of alveolar ventilation to dead space. This question tests the skill of reasoning that ventilation is controlled on two axes—rate and depth—rather than rate alone.', 'medium', '3B', 'Organ Systems', 'biology', 2, 90)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
