-- Q59 [Chemoreceptor Regulation] easy skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Chemoreceptor Regulation', 'An anesthesiologist monitors a sedated patient''s arterial blood during surgery. Which single change in the patient''s arterial blood, considered on its own, will most strongly increase the rate and depth of ventilation under normal physiological conditions?', '[{"label": "A", "text": "A rise in the partial pressure of oxygen"}, {"label": "B", "text": "A fall in the partial pressure of carbon dioxide"}, {"label": "C", "text": "A rise in the partial pressure of carbon dioxide"}, {"label": "D", "text": "A modest fall in the partial pressure of oxygen"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is C because under normal conditions the chemoreceptors that set ventilatory drive are most sensitive to arterial CO2: rising CO2 diffuses into the cerebrospinal fluid, generates H+, and stimulates the central chemoreceptors of the medulla, powerfully increasing the rate and depth of breathing. (Choice C) is correct: a rise in arterial CO2 is the primary and most potent stimulus to ventilation, acting mainly through the CO2/H+-sensitive central chemoreceptors. (Choice A) is incorrect: a rise in O2 does not stimulate breathing; if anything, high O2 removes any hypoxic contribution to drive, so ventilation would tend to decrease, not increase. (Choice B) is incorrect: a fall in CO2 (hypocapnia) removes the main chemoreceptor stimulus and depresses ventilation rather than increasing it. (Choice D) is incorrect: peripheral chemoreceptors respond to O2, but only a large, severe drop in arterial O2 meaningfully drives breathing; a modest fall has little effect and is far weaker than the CO2 stimulus under normal conditions. Skill: This item assesses the ability to identify the primary chemical stimulus regulating ventilation and relate it to central versus peripheral chemoreceptor sensitivity.', 'easy', '3B', 'Organ Systems', 'biology', 2, 60)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
