-- Q62 [Chemoreceptor Regulation] hard skill4 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Chemoreceptor Regulation', 'A healthy subject breathes a gas mixture in which inspired O2 is progressively lowered while CO2 is scrubbed out. Ventilation stays near baseline until arterial PO2 falls below roughly 60 mmHg, after which it rises steeply; in a separate trial, raising arterial PCO2 by just 3 mmHg at normal PO2 immediately increases ventilation. Which explanation best accounts for why the falling PO2 produced almost no ventilatory response until it became severe?', '[{"label": "A", "text": "Peripheral chemoreceptors detect dissolved O2 by Henry''s Law, so ventilation tracks arterial PO2 linearly across the entire range but the change was too small to measure until PO2 was severely low."}, {"label": "B", "text": "Over the normal-to-mild range of arterial PO2, hemoglobin remains nearly fully saturated, so peripheral chemoreceptor firing changes little until PO2 drops onto the steep part of the dissociation curve; central chemoreceptors, meanwhile, respond continuously to small CO2/H+ shifts."}, {"label": "C", "text": "The central chemoreceptors directly sense arterial PO2 and only trigger ventilation once O2 delivery to the medulla fails, which requires severe hypoxemia."}, {"label": "D", "text": "Lowering inspired O2 while scrubbing CO2 raised blood pH, and the resulting alkalosis suppressed the peripheral O2 response until hypoxemia became severe enough to override it."}]'::jsonb, 'B', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is B because peripheral chemoreceptors (carotid and aortic bodies) respond to arterial PO2, but their firing rate barely changes over the normal-to-mild range (roughly 100 down to ~60 mmHg) where hemoglobin stays near-fully saturated; only once PO2 falls onto the steep portion of the oxygen–hemoglobin dissociation curve does firing—and therefore ventilation—climb sharply. In contrast, central chemoreceptors in the medulla respond continuously and sensitively to small changes in CO2 (via CSF H+), which is why a 3 mmHg PCO2 rise immediately drives ventilation. This is precisely why CO2, not O2, is the primary breathing stimulus under normal conditions, with O2 becoming a significant drive only during severe hypoxemia. (Choice B) is correct: it correctly links the flat ventilatory response to the near-saturation plateau of the dissociation curve and identifies continuous central CO2 sensitivity as the normal drive. (Choice A) is incorrect: peripheral chemoreceptors respond to PO2, and the response is decidedly non-linear (flat until PO2 ~60 mmHg, then steep), not a small-but-linear signal—Henry''s Law describes dissolved gas but does not make ventilation track PO2 linearly here. (Choice C) is incorrect: central chemoreceptors sense CO2/H+, not O2; the O2 (hypoxic) drive is mediated by peripheral, not central, chemoreceptors. (Choice D) is incorrect: scrubbing CO2 can lower H+ (mild alkalosis) which does modestly blunt peripheral output, but the dominant reason ventilation stays flat is the near-flat PO2–firing relationship over the high-saturation range, not a pH gate that is ''overridden''; this option elevates a secondary effect to the primary cause. Skill: This item requires integrating physiological data (a threshold-like ventilatory response) with the underlying chemoreceptor mechanism rather than recalling a definition.', 'hard', '3B', 'Organ Systems', 'biology', 4, 120)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'partial_truth', 'Real principle (Henry''s Law, dissolved-O2 sensing) misapplied to force a linear PO2–ventilation relationship, ignoring the non-linear flat-then-steep firing curve.' FROM q
  UNION ALL
  SELECT id, 'C', 'misconception', 'Confuses central with peripheral chemoreceptors — attributes O2 sensing and hypoxic drive to central medullary receptors, which actually sense CO2/H+.' FROM q
  UNION ALL
  SELECT id, 'D', 'partial_truth', 'Elevates a real secondary effect (CO2-scrubbing alkalosis modestly blunting peripheral output) to the primary cause, obscuring the near-flat PO2–firing relationship.' FROM q;

-- Q63 [Gas Exchange & Pulmonary Circulation] medium skill4 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Gas Exchange & Pulmonary Circulation', 'Dry atmospheric air at sea level has a PO2 of about 160 mmHg, yet the PO2 of the gas inside a healthy person''s alveoli is only about 104 mmHg. It is this alveolar value, not the atmospheric one, that sets the gradient driving oxygen into the pulmonary capillary blood. Which combination of factors best explains why the alveolar PO2 that drives diffusion is substantially lower than the PO2 of the dry outside air?', '[{"label": "A", "text": "The dry outside air is warmed to body temperature, which lowers the partial pressure of oxygen while the total gas pressure rises above atmospheric"}, {"label": "B", "text": "Oxygen must first dissolve into the alveolar lining fluid, and its lower solubility compared with carbon dioxide reduces the oxygen partial pressure in the gas phase"}, {"label": "C", "text": "Inspired air is humidified so added water vapor claims part of the total pressure, resident alveolar CO2 dilutes the oxygen, and O2 is continuously removed into the blood"}, {"label": "D", "text": "Alveolar surfactant chemically binds a fixed fraction of the inhaled oxygen, removing it from the gas mixture before diffusion into the blood can occur"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is C because alveolar PO2 is set by the alveolar gas mixture, and three effects lower it below the dry-air value: inspired air is saturated with water vapor (which contributes about 47 mmHg of partial pressure and thus reduces the fraction available to the other gases), the alveoli always contain resident CO2 that dilutes the oxygen, and oxygen is continuously extracted across the respiratory membrane into the capillary blood. Because diffusion is driven by the partial pressure of O2 actually present at the alveolar surface, the alveolar value (about 104 mmHg), not the atmospheric value (about 160 mmHg), sets the O2 gradient. (Choice C) is correct: humidification, CO2 dilution, and ongoing O2 uptake into blood together account for the drop from 160 to about 104 mmHg, and diffusion follows the local alveolar partial pressure. (Choice A) is incorrect: warming inspired air to body temperature does add water vapor, but the total gas pressure in the alveoli remains essentially atmospheric rather than rising above it, so this misstates the pressure relationship. (Choice B) is incorrect: solubility in the lining fluid governs how much gas dissolves at a given partial pressure (Henry''s law), not the partial pressure of oxygen in the alveolar gas itself, so it does not explain why the gas-phase alveolar PO2 is lower. (Choice D) is incorrect: surfactant lowers surface tension and does not chemically bind or consume oxygen, so it plays no role in setting alveolar PO2. This question requires reasoning about how humidification, dilution, and continuous uptake determine the alveolar partial pressure that drives gas exchange.', 'medium', '3B', 'Organ Systems', 'biology', 4, 90)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'misconception', 'Attributes the drop to warming and falsely claims total alveolar pressure exceeds atmospheric' FROM q
  UNION ALL
