-- Q64 [Chemoreceptor Regulation] hard skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Chemoreceptor Regulation', 'A patient with long-standing severe lung disease has chronically retained CO2 for years, and their central chemoreceptors no longer increase ventilation in response to high arterial CO2. In a hospital, this patient is given a high concentration of supplemental oxygen, and their breathing slows dramatically. Which mechanism best explains why raising arterial O2 suppressed this patient''s drive to breathe?', '[{"label": "A", "text": "The supplemental oxygen directly stimulated the central chemoreceptors to lower their firing rate and slow the medullary rhythm"}, {"label": "B", "text": "Raising arterial O2 caused the carotid bodies to fire faster, and this increased input inhibited the diaphragm"}, {"label": "C", "text": "The added oxygen lowered arterial CO2, removing the strong central drive that was still maintaining the patient''s ventilation"}, {"label": "D", "text": "With central CO2 sensitivity blunted, the patient''s ventilation had been sustained mainly by carotid-body sensing of low O2, which the supplemental oxygen relieved"}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is D because in a patient whose central chemoreceptors have stopped responding to chronically elevated CO2, the normally dominant CO2 drive is absent, so ventilation comes to depend on the peripheral carotid bodies detecting low arterial O2; supplying oxygen removes this hypoxic stimulus, and breathing slows. (Choice D) is correct: it correctly identifies that the carotid bodies'' backup O2-sensing role becomes the main ventilatory drive once central CO2 sensitivity is lost, and that relieving hypoxia removes that drive. (Choice A) is incorrect: central chemoreceptors respond to CO2/H+ in the cerebrospinal fluid, not to O2, so raising O2 does not directly act on them. (Choice B) is incorrect: carotid bodies fire more when O2 is low, not when it is raised; supplemental oxygen would decrease, not increase, their firing, and their input drives rather than inhibits breathing. (Choice C) is incorrect: the scenario states the central CO2 response is already blunted, so a lost CO2 drive cannot be what the oxygen removed, and oxygen therapy does not lower CO2 in this way. Skill: This question tests the ability to reason about how the peripheral chemoreceptors provide a backup hypoxic ventilatory drive when the normally dominant central CO2 sensitivity is impaired.', 'hard', '3B', 'Organ Systems', 'biology', 2, 110)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'misconception', 'Believes central chemoreceptors sense O2 directly' FROM q
  UNION ALL
