  SELECT id, 'A', 'misconception', 'Assumes membrane transport of gases requires active transport/carrier proteins rather than passive diffusion' FROM q
  UNION ALL
  SELECT id, 'B', 'partial_truth', 'Confuses total gas pressure with the partial pressure of the individual diffusing gas' FROM q
  UNION ALL
  SELECT id, 'D', 'reversed_relationship', 'Treats hemoglobin binding as the cause of membrane crossing rather than a factor that maintains the gradient' FROM q;

-- Q68 [Gas Exchange & Pulmonary Circulation] medium skill4 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Gas Exchange & Pulmonary Circulation', 'Across the respiratory membrane, oxygen moves down a partial-pressure gradient of about 64 mmHg (104 vs. 40 mmHg), whereas carbon dioxide moves down a gradient of only about 5 mmHg (45 vs. 40 mmHg). Despite this far smaller driving gradient, CO2 crosses the membrane so readily that its exchange almost never limits gas transfer. Which property of CO2 best accounts for its ability to keep pace with O2 across the same membrane?', '[{"label": "A", "text": "CO2 has a larger molecular mass than O2, which increases the momentum with which it strikes and penetrates the membrane"}, {"label": "B", "text": "CO2 binds hemoglobin far more tightly than O2 does, pulling it across the membrane against the partial-pressure gradient"}, {"label": "C", "text": "CO2 is transported almost entirely as dissolved gas rather than as bicarbonate, giving it a steeper effective gradient than O2"}, {"label": "D", "text": "CO2 is roughly 20 times more soluble in the aqueous membrane and plasma than O2, so far more CO2 dissolves and diffuses per unit of partial-pressure difference"}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is D because the rate a gas diffuses across the moist respiratory membrane depends not only on its partial-pressure gradient but also on how readily it dissolves in the aqueous barrier; CO2 is roughly 20 times more soluble than O2, so many more CO2 molecules enter solution and cross per unit of gradient, allowing CO2 to keep pace despite its ~5 mmHg gradient being far smaller than O2''s ~64 mmHg gradient. (Choice D) is correct: CO2''s much greater aqueous solubility multiplies its diffusion rate for a given gradient, so its small gradient still moves as much gas as O2''s large gradient. (Choice A) is incorrect: heavier gases actually diffuse slightly more slowly (Graham''s law relates rate inversely to the square root of molar mass), and molecular momentum is not the operative factor across a liquid barrier—solubility is. (Choice B) is incorrect: diffusion across the membrane is driven by dissolved-gas partial pressures, not by hemoglobin binding, and no gas is pulled across against its own partial-pressure gradient; hemoglobin binding maintains the gradient but does not carry gas through the membrane. (Choice C) is incorrect: most CO2 in blood is in fact carried as bicarbonate and as carbamino compounds, not as dissolved gas, and it is CO2''s high solubility—not a steeper gradient—that speeds its membrane crossing. The skill assessed is applying the principle that diffusion rate across the respiratory membrane depends jointly on the partial-pressure gradient and the gas''s solubility in the aqueous barrier.', 'medium', '3B', 'Organ Systems', 'biology', 4, 90)
  RETURNING id
)
