-- Q69 [Gas Exchange & Pulmonary Circulation] medium skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Gas Exchange & Pulmonary Circulation', 'A cardiologist samples blood from a catheter threaded into a large vessel just as it enters the left atrium of a healthy patient. Compared with blood drawn simultaneously from the right ventricle, the atrial sample has a markedly higher partial pressure of oxygen. In which vessel was the atrial sample most likely drawn, and why does its oxygen content differ from the ventricular sample?', '[{"label": "A", "text": "A pulmonary vein, because blood entering the left atrium has already passed through the alveolar capillaries and been oxygenated"}, {"label": "B", "text": "A pulmonary artery, because arteries throughout the body always carry freshly oxygenated blood away from the heart"}, {"label": "C", "text": "A pulmonary vein, because veins entering the left atrium have just delivered oxygen to the systemic tissues"}, {"label": "D", "text": "A pulmonary artery, because blood leaving the right ventricle has already been oxygenated in the lungs"}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is A because the vessels that empty into the left atrium are the pulmonary veins, and the blood they carry has just traversed the alveolar capillary beds, where it equilibrated with alveolar air and became oxygenated — giving it a high partial pressure of oxygen relative to the deoxygenated blood in the right ventricle. (Choice A) is correct: blood returning to the left atrium arrives via the pulmonary veins after being oxygenated in the lungs, so its high PO2 versus the right-ventricular sample is exactly what is expected. (Choice B) is incorrect: it names the correct ''artery-carries-away-from-heart'' generality but misapplies it — the pulmonary artery carries deoxygenated blood to the lungs and does not empty into the left atrium, so it cannot be the high-PO2 atrial sample. (Choice C) is incorrect: it correctly identifies a pulmonary vein but gives a false reason — pulmonary veins have not delivered oxygen to systemic tissues; systemic oxygen delivery occurs in the systemic capillaries, and the pulmonary veins instead carry newly oxygenated blood from the lungs. (Choice D) is incorrect: the pulmonary artery leaves the right ventricle carrying deoxygenated blood toward the lungs — it has not yet been oxygenated — so it would be low, not high, in PO2 and does not feed the left atrium. Skill: This item requires applying knowledge of pulmonary circulation routing to reason about the oxygen state of blood in a named vessel rather than recalling a definition.', 'medium', '3B', 'Organ Systems', 'biology', 2, 90)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'reversed_relationship', 'Applies the systemic naming convention (arteries carry oxygenated blood) to the pulmonary artery, ignoring the pulmonary-circulation exception' FROM q
  UNION ALL
  SELECT id, 'C', 'partial_truth', 'Correct vessel (pulmonary vein) paired with a false mechanism — confuses pulmonary oxygen loading with systemic oxygen delivery' FROM q
  UNION ALL
