  SELECT id, 'A', 'misconception', 'Treats gas movement as governed by total dissolved-gas content rather than each gas''s independent partial-pressure gradient, sending both gases the same direction' FROM q
  UNION ALL
  SELECT id, 'B', 'reversed_relationship', 'Reverses both diffusion directions, misreading which compartment is higher for each gas' FROM q
  UNION ALL
