-- Q76 [Respiratory Immune Defense] medium skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Respiratory Immune Defense', 'A researcher tracks large inhaled dust particles as air is drawn rapidly through a person''s nostrils. Most of these large particles are deposited on the walls of the front of the nasal cavity, where coarse hairs project into the airstream, rather than continuing down into the bronchi and alveoli. Which mechanism best accounts for the removal of these large particles at this location?', '[{"label": "A", "text": "Alveolar macrophages migrate up into the nasal cavity and engulf the large particles before they can descend into the lower airways."}, {"label": "B", "text": "Secreted lysozyme in the nasal cavity dissolves the large particles by cleaving bonds in their outer surfaces."}, {"label": "C", "text": "The large particles diffuse across the thin nasal epithelium into the blood and are carried away before reaching the bronchi."}, {"label": "D", "text": "The nasal hairs and the abrupt, turbulent airflow cause large particles to collide with and stick to the mucus-coated surfaces of the anterior nasal cavity."}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is D because the coarse nasal hairs (vibrissae) disrupt the airstream and, together with the turbulent, changing-direction flow through the anterior nasal cavity, cause large, high-momentum particles to impact against the moist, mucus-coated walls and become trapped before they can reach the lower airways. (Choice D) is correct: nasal hairs plus turbulence-driven impaction deposit large particles onto sticky mucosal surfaces at the front of the nose, a purely mechanical filtration step. (Choice A) is incorrect: alveolar macrophages act deep in the alveoli, not in the nasal cavity, and they do not migrate upward to clear inhaled particles from the nose. (Choice B) is incorrect: lysozyme is an antibacterial enzyme that cleaves peptidoglycan in bacterial cell walls; it does not dissolve inert dust particles. (Choice C) is incorrect: large solid particles do not diffuse across the epithelium into the blood the way dissolved gases do; only gases follow that partial-pressure-driven diffusion pathway. This item tests the skill of identifying the physical mechanism by which a specific structural feature carries out a physiological defense function.', 'medium', '3B', 'Organ Systems', 'biology', 2, 75)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'process_step_confusion', 'Right defense cell, wrong location — attributes alveolar macrophage clearance to the nasal cavity' FROM q
  UNION ALL
  SELECT id, 'B', 'adjacent_fact', 'Real airway defense mechanism (lysozyme) misapplied to inert particles instead of bacteria' FROM q
  UNION ALL
  SELECT id, 'C', 'misconception', 'Confuses particulate filtration with the partial-pressure diffusion pathway used only by gases' FROM q;

-- Q77 [Thermoregulation] medium skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Thermoregulation', 'A researcher exposes an anesthetized mammal to a hot, dry environment and monitors blood flow in the mucosal lining of its nasal passages and trachea. Compared with the same animal at a thermoneutral temperature, what change in the airway mucosal vasculature would best help the animal shed excess body heat through its respiratory tract?', '[{"label": "A", "text": "Dilation of mucosal capillary beds, raising blood flow near the airway surface"}, {"label": "B", "text": "Constriction of mucosal capillary beds, lowering blood flow near the airway surface"}, {"label": "C", "text": "Constriction of mucosal capillary beds, which drives evaporative cooling by drying the mucosa"}, {"label": "D", "text": "Dilation of mucosal capillary beds, which conserves core heat by shunting blood inward"}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is A because dilating the mucosal capillary beds of the nasal passages and trachea increases warm blood flow just beneath the airway surface, and the large surface area of moving air lets that heat transfer to the airstream (and drive evaporation of mucosal water), so more heat is carried out of the body with each exhalation. (Choice A) is correct: vasodilation brings more warm blood to the airway surface, maximizing heat loss to inspired/expired air and supporting evaporative cooling — the appropriate response to a heat load. (Choice B) is incorrect: vasoconstriction reduces surface blood flow, which conserves heat rather than dissipating it; that is the response to cold, not heat. (Choice C) is incorrect: it correctly notes that evaporation cools, but constriction reduces the warm blood and moisture delivered to the surface, so it impairs rather than drives evaporative cooling. (Choice D) is incorrect: it pairs the correct vascular change (dilation) with the wrong outcome — dilation delivers blood outward toward the surface to lose heat, not inward to conserve it. This question tests the skill of reasoning about how a physiological mechanism responds to a described environmental challenge.', 'medium', '3B', 'Organ Systems', 'biology', 2, 90)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'reversed_relationship', 'Applies the opposite (cold-response) vascular change — vasoconstriction conserves heat, the reverse of what a heat load requires' FROM q
  UNION ALL
  SELECT id, 'C', 'partial_truth', 'Correctly states evaporation cools but attaches it to constriction, which actually reduces warm-blood/moisture delivery and impairs evaporative cooling' FROM q
  UNION ALL
  SELECT id, 'D', 'process_step_confusion', 'Names the correct vascular change (dilation) but assigns it the wrong physiological outcome (heat conservation via inward shunting instead of surface heat loss)' FROM q;

-- Q78 [Thermoregulation] medium skill2 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Thermoregulation', 'During intense exertion on a hot day, a dog begins breathing rapidly and shallowly, moving large volumes of air back and forth across its moist nasal and airway surfaces while its core temperature stabilizes. Which change in the air is most directly responsible for the heat that leaves the body during this behavior?', '[{"label": "A", "text": "Warm air expands as it enters the wider airways, and this expansion cools the surrounding tissue"}, {"label": "B", "text": "Liquid water on the airway lining converts to vapor, drawing heat from the surrounding tissue as it does so"}, {"label": "C", "text": "Carbon dioxide leaving the blood carries thermal energy out with each exhaled breath"}, {"label": "D", "text": "Inhaled cool air lowers tissue temperature by direct contact as it flows over the mucosa"}]'::jsonb, 'B', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is B because converting liquid water on the moist respiratory surfaces into water vapor requires latent heat, and that heat is pulled from the underlying tissue and blood; moving large volumes of air across these surfaces (panting) accelerates this evaporation, so the escaping water vapor carries body heat away and helps stabilize core temperature. (Choice B) is correct: evaporative cooling — the liquid-to-gas phase change absorbs heat of vaporization from the tissue, which is the direct route by which heat is dissipated during panting. (Choice A) is incorrect: any cooling from gas expansion in the airways is negligible and is not the mechanism of panting-based heat loss; the airways do not function as a meaningful expansion refrigerator, and this ignores the moist surfaces that make panting effective. (Choice C) is incorrect: CO2 is exhaled to regulate blood pH and gas exchange, not to carry away thermal energy; the thermal content of exhaled CO2 is trivial and is not why panting cools the body. (Choice D) is incorrect: inhaled air is actually warmed and humidified as it passes over the mucosa, so direct conductive contact with ''cool'' air is minor and, on a hot day, incoming air may be near or above body temperature — cooling instead depends on evaporation, not conduction. The skill required is applying the physical principle of evaporative heat loss to reason about how respiratory surfaces dissipate body heat.', 'medium', '3B', 'Organ Systems', 'biology', 2, 90)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'misconception', 'Applies adiabatic gas-expansion cooling to airways, an effect that is negligible and not the panting mechanism' FROM q
  UNION ALL
  SELECT id, 'C', 'adjacent_fact', 'Confuses CO2''s real roles (gas exchange, pH regulation) with heat transport, treating exhaled CO2 as the carrier of body heat' FROM q
  UNION ALL
  SELECT id, 'D', 'reversed_relationship', 'Assumes conductive cooling from cool inhaled air, ignoring that inhaled air is warmed/humidified and may be at or above body temperature on a hot day' FROM q;

-- Q79 [Thermoregulation] easy skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Thermoregulation', 'A physiologist compares two mammals exercising in the heat: a human, who becomes visibly drenched in sweat, and a dog, which does not sweat over most of its body and instead breathes rapidly with its tongue out. In the human, which organ system is chiefly responsible for dissipating the excess metabolic heat?', '[{"label": "A", "text": "The respiratory system, through rapid evaporation of water from the alveolar surfaces during forced breathing"}, {"label": "B", "text": "The urinary system, through increased production of warm urine that carries heat out of the body"}, {"label": "C", "text": "The integumentary system, through sweat-gland secretion and dilation of cutaneous blood vessels"}, {"label": "D", "text": "The digestive system, through radiation of heat from the large surface area of the intestinal lining"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is C because in humans the skin (integumentary system) is the primary thermoregulatory organ: eccrine sweat glands secrete fluid that evaporates from the body surface, and cutaneous vasodilation shunts warm blood near the surface so heat radiates away. The respiratory contribution to human heat loss is real but secondary; the dog''s panting illustrates the alternative respiratory-evaporative strategy used by species with few functional sweat glands. (Choice C) is correct: sweat evaporation plus cutaneous vasodilation make the skin the dominant route of heat dissipation in humans. (Choice A) is incorrect: respiratory evaporation contributes only a minor share of heat loss in humans, who rely on sweating; heavy respiratory-evaporative cooling (panting) is characteristic of non-sweating species like the dog, not humans. (Choice B) is incorrect: urine volume and temperature are governed by fluid and solute balance, not thermoregulation, and heat lost with excreted urine is negligible. (Choice D) is incorrect: the digestive tract is a site of heat production and absorption, not a regulated heat-dissipating surface; it is insulated within the body core rather than exposed for cooling. This item requires applying knowledge of organ-system function to predict the primary mechanism of heat loss in a specific species.', 'easy', '3B', 'Organ Systems', 'biology', 2, 60)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'partial_truth', 'Applies the dog''s panting (respiratory-evaporative) strategy to humans, overstating a real but secondary human heat-loss route' FROM q
  UNION ALL
  SELECT id, 'B', 'misconception', 'Confuses an excretory/fluid-balance organ with a thermoregulatory one, treating warm urine as a heat-dumping mechanism' FROM q
  UNION ALL
  SELECT id, 'D', 'misconception', 'Mistakes a core, insulated heat-producing/absorptive surface for an exposed heat-dissipating one' FROM q;

-- Q80 [Thermoregulation] hard skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Thermoregulation', 'A dog overheating on a hot day begins breathing rapidly and shallowly. Repeated arterial sampling shows that its blood CO2 and pH remain nearly unchanged even after several minutes of this behavior. Which feature of the breathing pattern best explains how it dissipates heat while leaving blood gases largely undisturbed?', '[{"label": "A", "text": "The rapid rate drives a large increase in alveolar ventilation, and the heat carried away in the extra exhaled CO2 is what cools the body"}, {"label": "B", "text": "Deep, forceful breaths maximize contact between blood and alveolar air, warming the exhaled gas and simultaneously boosting CO2 offloading"}, {"label": "C", "text": "The shallow breaths trigger reflex constriction of nasal and tracheal capillaries, shunting warm blood inward so that surface evaporation is minimized"}, {"label": "D", "text": "The high frequency moves air chiefly over the moist upper-airway surfaces, so evaporation removes heat while little fresh air reaches the alveoli for gas exchange"}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is D because panting is rapid, shallow breathing: each small tidal volume mostly ventilates the moist conducting airways (nose, pharynx, trachea) rather than the alveoli. Water evaporating from these warm, vascularized surfaces carries away large amounts of heat, while the shallow depth means the extra air exchanged is largely dead-space air that does not appreciably increase alveolar gas exchange. Because alveolar ventilation barely rises, CO2 elimination is not greatly boosted, so arterial CO2 and pH stay near normal — the animal cools without driving a respiratory alkalosis.
(Choice D) is correct: high-frequency, low-depth airflow maximizes evaporative cooling over upper-airway surfaces while keeping alveolar ventilation — and thus CO2 loss — nearly constant.
(Choice A) is incorrect: it wrongly claims a large rise in alveolar ventilation; that would blow off substantial CO2 and raise pH (respiratory alkalosis), contradicting the stable blood gases observed. Panting deliberately stays shallow to avoid this.
(Choice B) is incorrect: deep, forceful breaths would maximize alveolar gas exchange and CO2 offloading, disturbing blood pH, which is the opposite of what panting achieves; cooling comes from evaporation over airway surfaces, not from warming exhaled gas via deep alveolar contact.
(Choice C) is incorrect: it reverses the vascular response — effective heat loss requires vasodilation of airway capillary beds to deliver warm blood to evaporating surfaces, not constriction, and constriction would impair rather than aid cooling.
This question tests the skill of reasoning from an observed physiological outcome (heat loss with stable blood gases) back to the mechanism that produces it.', 'hard', '3B', 'Organ Systems', 'biology', 2, 120)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'reversed_relationship', 'Attributes cooling to a large rise in alveolar ventilation and heat carried in exhaled CO2, which would blow off CO2 and cause respiratory alkalosis — the opposite of the observed stable blood gases.' FROM q
  UNION ALL
  SELECT id, 'B', 'misconception', 'Assumes deep, forceful alveolar-maximizing breaths, contradicting the shallow nature of panting, and misattributes cooling to warming exhaled gas plus boosted CO2 offloading rather than evaporation.' FROM q
  UNION ALL
  SELECT id, 'C', 'reversed_relationship', 'Reverses the airway vascular response — invokes capillary constriction that would minimize evaporation, when effective panting requires vasodilation to deliver warm blood to evaporating surfaces.' FROM q;

-- Q81 [Thermoregulation] medium skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Thermoregulation', 'A person steps outside into freezing winter air and begins breathing through the nose. Which vascular change occurs in the capillary beds lining the nasal passages and trachea, and what is its physiological benefit?', '[{"label": "A", "text": "The capillaries constrict, reducing blood flow near the airway surface and limiting heat loss to inhaled air"}, {"label": "B", "text": "The capillaries dilate, increasing blood flow near the airway surface and limiting heat loss to inhaled air"}, {"label": "C", "text": "The capillaries constrict, reducing blood flow near the airway surface and speeding heat transfer to inhaled air"}, {"label": "D", "text": "The capillaries dilate, increasing blood flow near the airway surface and speeding evaporative cooling of inhaled air"}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is A because in cold conditions the smooth muscle around the nasal and tracheal capillary beds contracts, narrowing the vessels (vasoconstriction); this pulls warm blood away from the airway surface so that less core heat is transferred to the cold inhaled air and lost, helping the body conserve heat and maintain core temperature. (Choice A) is correct: constriction reduces surface blood flow, which minimizes conductive heat loss to inhaled air — the appropriate heat-conserving response. (Choice B) is incorrect: it correctly identifies the goal (limiting heat loss) but pairs it with dilation; dilation would increase warm blood at the surface and worsen heat loss, so the vascular direction is wrong. (Choice C) is incorrect: it correctly identifies constriction but misstates the purpose — the goal in cold is to conserve, not maximize, heat transfer to inhaled air. (Choice D) is incorrect: dilation with evaporative cooling describes a heat-dissipating (e.g., panting/hot-environment) response, the opposite of what cold demands. This question requires predicting a vascular response from an environmental scenario and connecting it to its thermoregulatory purpose.', 'medium', '3B', 'Organ Systems', 'biology', 2, 90)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'reversed_relationship', 'Correct thermoregulatory goal paired with the opposite vascular direction (dilation instead of constriction)' FROM q
  UNION ALL
  SELECT id, 'C', 'partial_truth', 'Correct mechanism (constriction) but inverted purpose — maximizing rather than conserving heat transfer' FROM q
  UNION ALL
  SELECT id, 'D', 'misconception', 'Confuses the cold-conservation response with the heat-dissipating dilation/evaporative-cooling (panting) response' FROM q;

-- Q82 [Thermoregulation] hard skill2 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Thermoregulation', 'On a hot day, a person''s facial skin flushes as arterioles feeding the dermal capillary beds widen, and separately their skin becomes slick as glandular secretions evaporate from its surface. In the respiratory tract, which single response uses the same heat-transfer mechanism as the skin flushing—and not the mechanism used by the slick skin?', '[{"label": "A", "text": "Increased evaporation of water from the moist lining of the conducting airways"}, {"label": "B", "text": "Widening of the mucosal capillary beds lining the nasal passages and trachea"}, {"label": "C", "text": "Rapid shallow panting that moves more air across the wet airway surface"}, {"label": "D", "text": "Constriction of the arterioles supplying the nasal and tracheal mucosa"}]'::jsonb, 'B', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is B because the described skin flushing is cutaneous vasodilation—widening of arterioles increases blood flow through surface capillaries so that warm blood radiates (conducts) heat directly across the tissue; the airway response using this identical mechanism is vasodilation of the nasal and tracheal mucosal capillary beds, which delivers warm blood to the airway surface to dump heat. The ''slick skin'' response is a different mechanism (evaporative cooling of secreted water), so the correct airway parallel must be the vascular/radiative one, not an evaporative one. (Choice B) is correct: dilating the mucosal capillary beds is the airway equivalent of cutaneous vasodilation—both move warm blood to a surface so heat is lost by radiation/conduction rather than by evaporation. (Choice A) is incorrect: evaporation of airway water is the respiratory parallel of the slick, evaporating skin (sweat), not of the flushing/vasodilation the question asks to match. (Choice C) is incorrect: panting increases evaporative heat loss by driving more airflow over the wet mucosa, so it mirrors the evaporative (slick-skin) mechanism, again the one the stem excludes. (Choice D) is incorrect: vasoconstriction reduces surface blood flow to conserve heat—it is the opposite (cold-response) of vasodilation, so it neither matches the flushing nor cools the body. The skill required is integrating parallel thermoregulatory mechanisms across two organ systems and discriminating radiative from evaporative heat loss.', 'hard', '3B', 'Organ Systems', 'biology', 2, 110)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'process_step_confusion', 'Matches the skin''s OTHER (evaporative) response instead of the flushing/vasodilation response the stem asks to mirror' FROM q
  UNION ALL
  SELECT id, 'C', 'process_step_confusion', 'Panting misread as the radiative parallel when it is actually an evaporative mechanism (airflow over wet mucosa), i.e., the excluded slick-skin mechanism' FROM q
  UNION ALL
  SELECT id, 'D', 'reversed_relationship', 'Vasoconstriction chosen as the vascular parallel, but it is the directional reversal (heat conservation) of the vasodilation being matched' FROM q;

-- Q83 [Airway Resistance & Airflow] medium skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Airway Resistance & Airflow', 'A clinician notes that a patient''s rapid breathing produces a clearly audible rushing sound over the trachea and large bronchi, yet auscultation over the periphery of the lung, where the smallest airways lie, reveals almost no sound. Which difference between these two regions best explains why airflow generates audible noise centrally but is nearly silent distally?', '[{"label": "A", "text": "The trachea has a smaller total cross-sectional area than the distal airways, so air moves through it more slowly and stays laminar, while the faster distal flow becomes turbulent and silent"}, {"label": "B", "text": "Gas exchange occurring in the distal airways absorbs the sound energy of the airflow, whereas the conducting trachea has no gas exchange to dampen the noise"}, {"label": "C", "text": "Air moves at high linear velocity through the trachea, producing turbulent, sound-generating flow, whereas the enormous combined cross-sectional area of the distal airways lowers velocity enough for flow to remain smooth and laminar"}, {"label": "D", "text": "Cartilage rings in the trachea vibrate audibly during any airflow, while the muscular distal airways cannot vibrate and therefore produce laminar flow"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is C because the trachea carries the entire tidal volume through one narrow tube, forcing air to a high linear velocity; high velocity drives the flow into the turbulent regime (high Reynolds number), and turbulence generates the audible rushing breath sounds heard centrally. As the airway tree branches, the summed cross-sectional area of all the distal passages becomes enormous, so by continuity the linear velocity of the air falls dramatically. At these low velocities flow stays smooth and laminar (low Reynolds number), which is silent, so peripheral auscultation is nearly quiet. (Choice C) is correct: it correctly pairs high central velocity with turbulence/sound and low distal velocity with laminar/silent flow. (Choice A) is incorrect: it reverses the velocity relationship — the trachea has the smallest, not largest, total cross-sectional area, so central velocity is highest, not lowest, and central flow is turbulent, not laminar. (Choice B) is incorrect: sound is not generated by flow smoothness being ''absorbed'' by gas exchange; silence distally results from laminar flow at low velocity, and audible sound centrally results from turbulence, independent of where diffusion occurs. (Choice D) is incorrect: breath sounds arise from turbulent airflow, not from tracheal cartilage vibrating, and cartilage does not determine whether flow is laminar or turbulent. This question assesses the skill of reasoning about how airway geometry sets flow velocity and thereby whether airflow is turbulent (audible) or laminar (silent).', 'medium', '3B', 'Organ Systems', 'biology', 2, 90)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'reversed_relationship', 'Swaps the cross-sectional-area/velocity relationship so the trachea is called slow/laminar and the distal airways fast/turbulent' FROM q
  UNION ALL
  SELECT id, 'B', 'misconception', 'Attributes distal silence to sound energy being absorbed by gas exchange rather than to laminar low-velocity flow' FROM q
  UNION ALL
  SELECT id, 'D', 'misconception', 'Attributes central breath sounds to cartilage-ring vibration rather than to turbulent airflow' FROM q;

-- Q84 [Respiratory Immune Defense] easy skill1 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Respiratory Immune Defense', 'In the trachea and bronchi, inhaled dust and bacteria become trapped in a layer of mucus resting atop the epithelial lining. In a healthy airway, which mechanism is chiefly responsible for moving this particle-laden mucus out of the conducting airways?', '[{"label": "A", "text": "Wandering macrophages crawl through the mucus and physically drag trapped particles up to the pharynx"}, {"label": "B", "text": "Secreted lysozyme dissolves the mucus layer, allowing gravity to drain the trapped particles downward into the alveoli"}, {"label": "C", "text": "The high airflow velocity of each exhaled breath blows the entire mucus sheet out through the nose and mouth"}, {"label": "D", "text": "Coordinated beating of epithelial cilia sweeps the mucus sheet upward toward the pharynx, where it is swallowed or expelled"}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is D because the conducting airways are lined by ciliated epithelium topped with a mucus sheet; the cilia beat in a coordinated, wave-like rhythm that propels the mucus (and any particles trapped in it) upward toward the pharynx, where it is swallowed or coughed out—the mucociliary escalator.

(Choice D) is correct: The synchronized upward stroke of the cilia continuously moves the mucus sheet toward the pharynx, carrying trapped debris out of the lungs.
(Choice A) is incorrect: Macrophages are the principal defense in the alveoli, which lack cilia and mucus; they engulf particles by phagocytosis rather than dragging mucus up the airways.
(Choice B) is incorrect: Lysozyme is an antibacterial enzyme that cleaves bacterial cell walls; it does not dissolve mucus, and directing particles downward toward the alveoli would defeat airway clearance rather than achieve it.
(Choice C) is incorrect: Clearance does not depend on exhaled airflow blowing the mucus out; the escalator works continuously and slowly through ciliary action, independent of breath velocity.

Skill: This question tests the ability to identify the normal cellular mechanism (ciliary transport of a mucus sheet) that clears particles from the conducting airways.', 'easy', '3B', 'Organ Systems', 'biology', 1, 60)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'adjacent_fact', 'Correctly recalls that macrophages are a respiratory defense but misassigns them to mucus transport in the conducting airways rather than phagocytosis in the alveoli' FROM q
  UNION ALL
  SELECT id, 'B', 'misconception', 'Invokes a real airway enzyme (lysozyme) but attributes to it a mucus-dissolving, gravity-drainage role that reverses the direction of clearance' FROM q
  UNION ALL
  SELECT id, 'C', 'misconception', 'Assumes bulk airflow (breath velocity) rather than continuous ciliary action drives mucus clearance' FROM q;

-- Q85 [Respiratory Immune Defense] medium skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Respiratory Immune Defense', 'A researcher isolates a soluble enzyme abundant in human nasal secretions and airway mucus. When purified bacteria are added to a solution of this enzyme, gram-positive species rupture and lyse, whereas the enzyme has little direct effect on enveloped viruses or fungal spores. Which action of the enzyme best accounts for this selective bactericidal effect?', '[{"label": "A", "text": "It hydrolyzes the glycosidic bonds of the peptidoglycan cell wall, compromising the structure that resists osmotic pressure"}, {"label": "B", "text": "It oxidizes membrane phospholipids, generating pores that dissipate the bacterial proton gradient"}, {"label": "C", "text": "It binds and sequesters free iron, starving bacteria of a nutrient required for growth"}, {"label": "D", "text": "It cleaves the bacterial genome, blocking transcription of essential genes"}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is A because the enzyme described is lysozyme, which hydrolyzes the β(1→4) glycosidic linkages of peptidoglycan; peptidoglycan is the rigid mesh that lets a bacterium withstand osmotic influx, so cleaving it causes the cell to swell and lyse. Gram-positive bacteria have a thick, exposed peptidoglycan layer, making them especially vulnerable, while viruses and fungi lack peptidoglycan and are therefore spared. (Choice A) is correct: degradation of the peptidoglycan wall removes the osmotic support of the cell, explaining both the lysis and the selectivity for peptidoglycan-bearing (gram-positive) bacteria. (Choice B) is incorrect: this describes an oxidative or pore-forming mechanism (as in some antimicrobial peptides or the respiratory burst), not the hydrolytic wall-degrading action of the airway enzyme, and it would not selectively spare enveloped viruses. (Choice C) is incorrect: iron sequestration describes lactoferrin/transferrin, a nutritional-immunity strategy, not an enzyme that ruptures cells by cleaving a structural polymer. (Choice D) is incorrect: cleaving the genome describes a nuclease acting on DNA; it would not produce immediate osmotic rupture of the intact cell nor account for the gram-positive selectivity, which tracks the wall polymer rather than the genome. The relevant Skill is reasoning about how a chemical defense mechanism of the respiratory tract produces a specific, structurally determined outcome.', 'medium', '3B', 'Organ Systems', 'biology', 2, 90)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'misconception', 'Attributes a different antimicrobial mechanism (oxidative/pore-forming) to the airway enzyme' FROM q
  UNION ALL
  SELECT id, 'C', 'adjacent_fact', 'Correct airway/mucosal defense (iron sequestration by lactoferrin) attributed to the wrong molecule' FROM q
  UNION ALL
  SELECT id, 'D', 'process_step_confusion', 'Confuses cell-wall hydrolysis with nuclease action on the genome' FROM q;

-- Q86 [Respiratory Immune Defense] medium skill2 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Respiratory Immune Defense', 'A researcher engineers mice whose airway epithelial cells can no longer transport a certain dimeric antibody isotype across the mucosal epithelium into the fluid layer lining the trachea and bronchi. When these mice are exposed to aerosolized bacteria, a much larger number of bacteria are recovered from and within the airway epithelium than in wild-type mice. Which mechanism best explains why the missing antibody normally protects the airway?', '[{"label": "A", "text": "After secretion into the airway fluid, the antibody activates the complement cascade to lyse pathogens directly on the mucosal surface"}, {"label": "B", "text": "Once secreted into the airway lining fluid, the antibody binds surface molecules on inhaled pathogens, so the coated pathogens cannot adhere to the epithelium and are cleared before invading"}, {"label": "C", "text": "The antibody enters airway epithelial cells and triggers their apoptosis, sloughing off any cells that pathogens have contacted"}, {"label": "D", "text": "The antibody crosses into the bloodstream, where it opsonizes pathogens for phagocytosis by circulating neutrophils"}]'::jsonb, 'B', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is B because the dimeric antibody transported across the airway epithelium into the mucus lining fluid is secretory IgA; in that fluid it binds antigens on the surface of inhaled pathogens, coating them so they cannot attach to epithelial cells (immune exclusion) and remain trapped in mucus to be swept away by the mucociliary escalator. When the transport step is lost, the mucosal surface is left uncoated, so more bacteria adhere to and penetrate the epithelium, exactly the phenotype observed. (Choice B) is correct: secretory IgA acts at the luminal mucosal surface by binding and neutralizing pathogens and preventing their attachment, which is precisely the function lost when transport is blocked. (Choice A) is incorrect: secretory IgA is a poor activator of the classical complement cascade and defends mainly by neutralization/immune exclusion, not by lysing pathogens via complement on the mucosal surface. (Choice C) is incorrect: the protective antibody works extracellularly in the airway fluid by coating pathogens; it does not enter epithelial cells to induce apoptosis, and destroying epithelium would not explain the protection. (Choice D) is incorrect: the relevant defense is on the luminal mucosal surface, and the antibody is transported outward into the airway lining fluid, not inward to the bloodstream to arm circulating neutrophils. Skill: This item tests the ability to reason from an experimental manipulation to the physiological mechanism by which mucosal antibody defends the respiratory epithelium.', 'medium', '3B', 'Organ Systems', 'biology', 2, 90)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'misconception', 'Attributes a plausible-sounding but incorrect effector mechanism (complement-mediated surface lysis) to secretory IgA, which is actually a weak complement activator that works by immune exclusion' FROM q
  UNION ALL
  SELECT id, 'C', 'process_step_confusion', 'Confuses the site/mode of action, placing the antibody inside epithelial cells inducing apoptosis rather than acting extracellularly in the lumen' FROM q
  UNION ALL
  SELECT id, 'D', 'reversed_relationship', 'Reverses the direction of transport and site of action (inward to blood/neutrophils) instead of outward to the luminal mucosal surface' FROM q;

-- Q87 [Respiratory Immune Defense] hard skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Respiratory Immune Defense', 'A researcher studies a person who inhales pollen for the first time versus a second time weeks later. On first exposure there is no airway reaction, but on the second exposure the same pollen triggers rapid local swelling, mucus secretion, and bronchial narrowing within minutes. Which sequence best explains why only the second exposure produces this immediate airway response?', '[{"label": "A", "text": "First exposure activates alveolar macrophages that engulf the pollen; on re-exposure the macrophages release histamine directly onto the airway epithelium, producing swelling and mucus."}, {"label": "B", "text": "First exposure raises mucosal IgA levels; on re-exposure the IgA neutralizes the pollen in the mucus layer, and the resulting antigen-antibody clumps mechanically irritate the airway to cause narrowing."}, {"label": "C", "text": "First exposure generates antibodies that coat resident airway mast cells; on re-exposure the pollen cross-links these surface antibodies, triggering the cells to release preformed histamine and other mediators."}, {"label": "D", "text": "First exposure sensitizes airway chemoreceptors to the pollen; on re-exposure these chemoreceptors reflexively drive bronchoconstriction and mucus release before any immune cell is involved."}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is C because a first (sensitizing) exposure prompts the immune system to make antibodies specific for the pollen antigen, and these antibodies bind to the surface of mast cells resident in the airway tissue. On the second exposure, the antigen bridges (cross-links) adjacent surface-bound antibodies, and this binding is the trigger that causes the mast cell to degranulate, releasing preformed mediators such as histamine that produce vasodilation/swelling, increased mucus, and bronchial smooth-muscle narrowing within minutes — explaining why the immediate reaction appears only on re-exposure. (Choice C) is correct: it correctly sequences sensitization (antibody production and mast-cell surface loading) followed by antigen cross-linking of surface antibodies as the degranulation trigger, matching the two-step mast-cell mechanism. (Choice A) is incorrect: alveolar macrophages phagocytose particulates but are not the reservoir of preformed histamine and do not degranulate histamine in response to surface-bound antibody; this misattributes the mast-cell mechanism to macrophages. (Choice B) is incorrect: mucosal IgA does help trap and neutralize antigens in mucus, but that protective action does not by itself cause the rapid histamine-driven swelling, mucus, and bronchoconstriction seen here — the immediate reaction is mediator release, not mechanical irritation by antigen-antibody clumps. (Choice D) is incorrect: airway/central chemoreceptors respond to CO2 and H+ to adjust ventilation, not to specific antigens, and they are not a memory mechanism that could distinguish first from second pollen exposure. Skill: This item tests the ability to reason through a multi-step immunologic mechanism (sensitization then antigen-triggered mediator release) rather than to recall a single definition.', 'hard', '3B', 'Organ Systems', 'biology', 2, 110)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'misconception', 'Attributes the preformed-histamine/degranulation reservoir to alveolar macrophages, conflating two distinct airway-defense cell types.' FROM q
  UNION ALL
  SELECT id, 'B', 'partial_truth', 'Starts from a true airway defense (mucosal IgA trapping antigen) but grafts on a fabricated mechanical-irritation pathway to explain the rapid reaction.' FROM q
  UNION ALL
  SELECT id, 'D', 'adjacent_fact', 'Borrows the real CO2/H+ chemoreceptor concept and misapplies it as an antigen-specific memory/reflex mechanism.' FROM q;

-- Q88 [Respiratory Immune Defense] medium skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Respiratory Immune Defense', 'Airway epithelial cells secrete small cationic peptides that insert into and permeabilize the lipid membranes of inhaled microbes, killing bacteria that are not susceptible to peptidoglycan-cleaving enzymes as well as some fungi and enveloped viruses. Which property of these peptides best explains how a single molecule can compromise such structurally different microbes?', '[{"label": "A", "text": "They hydrolyze the glycosidic bonds of peptidoglycan, a polymer common to bacteria, fungi, and enveloped viruses."}, {"label": "B", "text": "They tag microbes for engulfment by opsonizing their surfaces so that alveolar macrophages recognize them."}, {"label": "C", "text": "They neutralize microbes by cross-linking surface antigens the way a secreted dimeric antibody does at the mucosal surface."}, {"label": "D", "text": "They physically disrupt the integrity of negatively charged microbial membranes, a target shared across bacteria, fungi, and enveloped viruses."}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is D because antimicrobial peptides such as defensins are small, positively charged (cationic) molecules that are drawn to the anionic lipids exposed on microbial surfaces and then insert into the lipid bilayer, forming pores or otherwise destabilizing the membrane; because a lipid membrane is a feature shared by bacteria, fungi, and enveloped viruses, one peptide mechanism can act broadly against all three, independent of any specific cell-wall polymer. (Choice D) is correct: membrane permeabilization targets the negatively charged lipid bilayer common to these diverse microbes, explaining the broad reach of a single peptide. (Choice A) is incorrect: hydrolyzing peptidoglycan glycosidic bonds is the mechanism of lysozyme, and peptidoglycan is a bacterial cell-wall polymer that fungi and enveloped viruses do not possess, so it cannot account for activity against those microbes. (Choice B) is incorrect: opsonization coats microbes to promote phagocytosis by macrophages but does not itself kill by disrupting membranes, and defensins act directly rather than by flagging targets for other cells. (Choice C) is incorrect: cross-linking and neutralizing antigens describes the action of secreted (mucosal IgA) antibody, an adaptive, antigen-specific mechanism distinct from the direct physicochemical membrane attack of a cationic peptide. This question tests the skill of distinguishing the mechanisms of distinct innate airway chemical defenses.', 'medium', '3B', 'Organ Systems', 'biology', 2, 90)
  RETURNING id
)
