-- Q89 [Respiratory Immune Defense] easy skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Respiratory Immune Defense', 'The alveoli present an extremely thin, moist surface across which gases diffuse into and out of the blood. Unlike the trachea and bronchi, the alveolar walls lack a coating of mucus swept along by cilia. Which feature of the alveoli best explains why they must instead rely on migrating cells that engulf inhaled particles?', '[{"label": "A", "text": "A mucus-and-cilia lining would thicken the barrier and slow the diffusion of oxygen and carbon dioxide"}, {"label": "B", "text": "Alveoli lie too deep in the lungs for air currents to carry particles back out through the airways"}, {"label": "C", "text": "The alveolar surface is too alkaline for cilia to beat effectively"}, {"label": "D", "text": "Alveoli have no blood supply, so immune cells cannot be delivered from the circulation"}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is A because the alveolus is specialized for gas exchange, which requires the thinnest possible barrier between air and blood; adding a mucus layer and ciliated cells would increase the diffusion distance and impair oxygen and carbon dioxide exchange, so the alveoli instead depend on wandering (alveolar) macrophages that crawl over the surface and phagocytose inhaled particles. (Choice A) is correct: a thicker, mucus-coated wall would lengthen the path gases must diffuse, reducing gas-exchange efficiency, which is why alveoli sacrifice the mucociliary escalator in favor of macrophages. (Choice B) is incorrect: particles are not cleared from alveoli by air currents at all, and the depth of the alveoli is not the reason cilia are absent; the constraint is the need for a thin diffusion barrier. (Choice C) is incorrect: alveolar surface pH is not the reason cilia are absent, and cilia in the upper airway function in the same body environment; the trade-off is structural (barrier thickness), not chemical. (Choice D) is incorrect: alveoli are surrounded by a dense pulmonary capillary network, so they are richly supplied with blood; the point is that a resident phagocyte, not a circulatory limitation, handles particle clearance where mucus cannot be used. This question tests the skill of relating the structure of a gas-exchange surface to the immune defense strategy it can support.', 'easy', '3B', 'Organ Systems', 'biology', 2, 70)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'misconception', 'Attributes cilia absence to alveolar depth/air-current clearance rather than the thin-barrier structural constraint' FROM q
  UNION ALL
  SELECT id, 'C', 'adjacent_fact', 'Invents a chemical (pH) reason cilia cannot function, substituting a plausible-sounding constraint for the real structural one' FROM q
  UNION ALL
  SELECT id, 'D', 'misconception', 'Falsely claims alveoli lack a blood supply, contradicting the dense pulmonary capillary network' FROM q;

-- Q90 [Respiratory Immune Defense] hard skill2 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Respiratory Immune Defense', 'A researcher studies a mouse strain whose alveolar macrophages are selectively depleted, while nasal hairs, the mucus layer, ciliary beating, and secreted lysozyme and IgA all remain fully intact. Compared with wild-type mice, which challenge is this strain LEAST able to clear?', '[{"label": "A", "text": "Large (~15 micron) dust particles entering the nasal cavity during inhalation"}, {"label": "B", "text": "Fine (~1 micron) particulate matter and inhaled bacteria that reach the alveoli"}, {"label": "C", "text": "Bacteria trapped in the mucus lining the trachea and bronchi"}, {"label": "D", "text": "Airborne allergens contacting the mucosal surface of the upper airway"}]'::jsonb, 'B', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is B because the mucociliary escalator (mucus plus beating cilia) lines only the conducting airways and cannot reach the alveoli, which have no cilia; clearance of the small particles and microbes that penetrate this deep into the respiratory zone depends on phagocytosis by alveolar macrophages. With the macrophages depleted but every conducting-airway defense intact, only the deep-lung challenge is left uncleared. (Choice B) is correct: ~1 micron particles and bacteria are small enough to bypass upstream filtration and settle in the alveoli, where macrophages are the sole clearance mechanism — exactly the function that is missing. (Choice A) is incorrect: large ~15 micron particles are trapped by nasal hairs and the mucus of the upper airway, defenses that are explicitly intact, so their clearance is unaffected. (Choice C) is incorrect: bacteria in tracheal/bronchial mucus are swept upward by the intact mucociliary escalator toward the pharynx, independent of macrophages. (Choice D) is incorrect: upper-airway allergens are handled at the mucosal surface by intact mucus, secreted IgA, and lysozyme, not by alveolar macrophages. This question tests the skill of predicting the physiological consequence of a specific defect by mapping each defense mechanism to the airway region it protects.', 'hard', '3B', 'Organ Systems', 'biology', 2, 95)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'process_step_confusion', 'Attributes deep-lung clearance failure to a particle size actually stopped upstream by intact nasal-hair/mucus filtration' FROM q
  UNION ALL
  SELECT id, 'C', 'adjacent_fact', 'Confuses macrophage-dependent alveolar clearance with the mucociliary escalator that handles conducting-airway bacteria' FROM q
  UNION ALL
  SELECT id, 'D', 'misconception', 'Assumes macrophages clear upper-airway antigens rather than the intact mucosal IgA/lysozyme surface defenses' FROM q;

-- Q91 [Respiratory Immune Defense] medium skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'Respiratory Immune Defense', 'A researcher studies a patient whose airway epithelium produces a normal quantity of mucus, but whose ciliated cells beat weakly and in an uncoordinated fashion. Compared with a healthy person, this patient''s lower airway is most likely to show which outcome after inhaling airborne bacteria?', '[{"label": "A", "text": "Inhaled bacteria pass freely through the airway secretions because trapping depends on ciliary beating"}, {"label": "B", "text": "Inhaled bacteria are neither caught nor cleared, because both trapping and upward transport are performed by the cilia"}, {"label": "C", "text": "Inhaled bacteria are initially caught in the airway secretions but tend to accumulate rather than being swept back up toward the pharynx"}, {"label": "D", "text": "Inhaled bacteria are trapped and cleared normally, because upward transport is driven by the mucus layer itself"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is C because the two components of the mucociliary escalator have distinct jobs: the sticky mucus layer (secreted by goblet cells) physically traps inhaled microbes and particles, while the coordinated beating of the cilia provides the transport that propels that mucus—and its trapped load—upward toward the pharynx to be swallowed or expelled. With mucus production intact but ciliary beating weak and uncoordinated, bacteria are still caught in the secretions, but the transport step fails, so the contaminated mucus stagnates and accumulates in the lower airway, predisposing to infection. (Choice C) is correct: trapping (a mucus function) is preserved, but clearance (a ciliary function) is impaired, so trapped material builds up instead of being removed. (Choice A) is incorrect: trapping is a property of the sticky mucus layer, not of the cilia; microbes do not pass freely simply because cilia are dysfunctional. (Choice B) is incorrect: it wrongly assigns both trapping and transport to the cilia; trapping is the role of the mucus, so catching still occurs. (Choice D) is incorrect: it reverses the roles by claiming the mucus layer drives its own upward transport; the mucus is passive and relies on ciliary beating for movement, so clearance is not normal here. This question requires the skill of reasoning about how the distinct functions of two structures combine to accomplish a physiological process.', 'medium', '3B', 'Organ Systems', 'biology', 2, 90)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'reversed_relationship', 'Attributes the trapping function to the cilia rather than the mucus, so a ciliary defect is wrongly assumed to abolish trapping' FROM q
  UNION ALL
  SELECT id, 'B', 'misconception', 'Collapses both roles (trapping and transport) onto the cilia, ignoring that the mucus layer is the trapping agent' FROM q
  UNION ALL
  SELECT id, 'D', 'reversed_relationship', 'Reverses the escalator mechanism by treating the passive mucus layer as the driver of its own upward transport' FROM q;

-- Q92 [pH Control & the Bicarbonate Buffer] hard skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'pH Control & the Bicarbonate Buffer', 'Ordinarily a buffer is most effective only when the surrounding pH is within about one unit of its pKa. The bicarbonate system (CO2 + H2O ⇌ H2CO3 ⇌ H+ + HCO3−) has a pKa near 6.1, yet it is the body''s most important buffer at a physiological pH of about 7.4 — more than a full unit away. Which feature of this system best explains why it buffers so effectively despite this mismatch?', '[{"label": "A", "text": "The unusually large equilibrium constant for the reaction of CO2 with water lets a small amount of bicarbonate neutralize an essentially unlimited quantity of added acid without any change in gas exchange."}, {"label": "B", "text": "Dissolved CO2 raises the effective pKa of the system to about 7.4, so at physiological pH the buffer is operating exactly at its point of maximum capacity."}, {"label": "C", "text": "Because the lungs continuously add CO2 to the blood, the H2CO3 concentration is held far above that of bicarbonate, and this excess acid is what neutralizes any base that is added."}, {"label": "D", "text": "Because CO2 can be continuously exhaled by the lungs, the system''s acid component is not fixed, so added H+ can be consumed and the resulting CO2 removed rather than allowed to accumulate and blunt further buffering."}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is D because the bicarbonate system is an ''open'' buffer: added H+ is consumed by HCO3− to form H2CO3 and then CO2, and because the lungs continuously exhale that CO2, the acid product is removed from the system instead of accumulating. In a closed buffer, accumulating conjugate acid would drive the equilibrium back and exhaust buffering capacity as pH moves away from the pKa; ventilation-adjustable CO2 removal frees the bicarbonate system from that limitation, which is why it remains effective even though its pKa (~6.1) lies more than a unit below physiological pH. (Choice D) is correct: it identifies the open, ventilation-coupled removal of CO2 as the reason the system buffers effectively despite the pKa mismatch. (Choice A) is incorrect: the equilibrium constant for CO2 hydration is actually small (the reaction favors dissolved CO2), and no chemistry lets a finite amount of buffer neutralize ''unlimited'' acid without changing gas exchange—the answer even contradicts the open-system mechanism by denying any role for ventilation. (Choice B) is incorrect: dissolved CO2 does not shift the intrinsic pKa to 7.4; the pKa remains ~6.1, and the system''s effectiveness comes from CO2 removal, not from the buffer sitting at its maximum-capacity point. (Choice C) is incorrect: at physiological pH bicarbonate is present in large excess over carbonic acid (roughly 20:1), not the reverse, and buffering of added acid is done by that bicarbonate reserve consuming H+, not by an excess of H2CO3 neutralizing base. This question tests the skill of reasoning about how the open, ventilation-coupled nature of the CO2/bicarbonate system extends its buffering capacity beyond the usual pKa ± 1 rule.', 'hard', '3B', 'Organ Systems', 'biology', 2, 110)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'misconception', 'Inverts the true magnitude of the CO2-hydration equilibrium constant and claims a finite buffer can neutralize unlimited acid' FROM q
  UNION ALL
  SELECT id, 'B', 'partial_truth', 'Correctly notes the pKa/pH mismatch matters but invents a pKa shift to 7.4 to force max-capacity operation' FROM q
  UNION ALL
  SELECT id, 'C', 'reversed_relationship', 'Reverses the physiological ~20:1 bicarbonate-to-carbonic-acid ratio and misassigns the buffering role to excess H2CO3' FROM q;

-- Q93 [pH Control & the Bicarbonate Buffer] medium skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'pH Control & the Bicarbonate Buffer', 'A competitive swimmer deliberately takes several rapid, deep breaths before submerging, exhaling carbon dioxide from the blood faster than her metabolism produces it. In the bloodstream, dissolved CO2 is in equilibrium with carbonic acid, which in turn is in equilibrium with hydrogen ions and bicarbonate ions. As this rapid breathing continues, how do the blood hydrogen-ion concentration and pH change?', '[{"label": "A", "text": "Hydrogen-ion concentration decreases and pH rises"}, {"label": "B", "text": "Hydrogen-ion concentration increases and pH falls"}, {"label": "C", "text": "Hydrogen-ion concentration increases and pH rises"}, {"label": "D", "text": "Hydrogen-ion concentration decreases and pH falls"}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is A because removing CO2 from the blood by rapid breathing lowers the CO2 concentration, which pulls the coupled equilibrium (CO2 + H2O ⇌ H2CO3 ⇌ H+ + HCO3−) to the left; this leftward shift consumes free H+, so hydrogen-ion concentration drops and, because pH is inversely related to [H+], blood pH rises (a respiratory alkalosis). (Choice A) is correct: exhaling CO2 faster than it is produced shifts the buffer toward CO2, consuming H+ and lowering [H+], which raises pH. (Choice B) is incorrect: it reverses the direction of the shift — increased [H+] with lower pH describes what happens when CO2 accumulates (hypoventilation/breath-holding), not when it is blown off. (Choice C) is incorrect: it pairs the correct pH change with the wrong [H+] change; a rising pH must come from a falling [H+], so [H+] cannot increase here. (Choice D) is incorrect: it pairs the correct [H+] change with the wrong pH direction; because pH varies inversely with [H+], a decrease in [H+] cannot lower pH. This question tests the skill of reasoning about the direction a coupled buffer equilibrium shifts when a reactant (CO2) is removed.', 'medium', '3B', 'Organ Systems', 'biology', 2, 90)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'reversed_relationship', 'Applies the CO2-accumulation (hypoventilation/breath-holding) outcome to a CO2-removal scenario, reversing the equilibrium shift direction' FROM q
  UNION ALL
  SELECT id, 'C', 'partial_truth', 'Correct pH direction paired with an [H+] change that contradicts the inverse [H+]-pH relationship' FROM q
  UNION ALL
  SELECT id, 'D', 'partial_truth', 'Correct [H+] direction paired with a pH change that contradicts the inverse [H+]-pH relationship' FROM q;

-- Q94 [pH Control & the Bicarbonate Buffer] medium skill2 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'pH Control & the Bicarbonate Buffer', 'A patient with a long-standing lung disease chronically retains CO2, keeping arterial CO2 persistently elevated for weeks. Over this period, arterial pH is found to have drifted back toward normal even though CO2 remains high. Which renal action most directly accounts for this slow return of pH toward normal?', '[{"label": "A", "text": "The kidneys excrete large amounts of bicarbonate in the urine, lowering plasma bicarbonate to match the elevated CO2"}, {"label": "B", "text": "The kidneys reabsorb and generate additional bicarbonate over days, raising plasma bicarbonate to offset the retained acid"}, {"label": "C", "text": "The kidneys increase excretion of dissolved CO2 directly into the urine, lowering arterial CO2 back toward normal"}, {"label": "D", "text": "The kidneys rapidly increase ventilation-independent removal of hydrogen ions within minutes, before any bicarbonate change occurs"}]'::jsonb, 'B', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is B because in chronic respiratory acidosis the retained CO2 drives the bicarbonate equilibrium toward more H+, and the kidneys compensate slowly (over days) by reabsorbing filtered bicarbonate and generating new bicarbonate, raising plasma HCO3- so that the HCO3-/CO2 ratio—and thus pH—moves back toward normal despite the persistently high CO2. (Choice B) is correct: retaining and generating bicarbonate adds base that buffers the retained acid load and pulls pH upward, which is the defining slow metabolic (renal) offset to a respiratory disturbance. (Choice A) is incorrect: excreting bicarbonate would lower plasma HCO3- and worsen the acidosis rather than correct it; bicarbonate loss is the renal response to alkalosis, not acidosis. (Choice C) is incorrect: the kidneys do not excrete dissolved CO2 as such—CO2 clearance is a respiratory (lung) function, and renal compensation works by adjusting bicarbonate and H+ handling, not by exhaling or excreting CO2. (Choice D) is incorrect: renal compensation is slow, unfolding over days rather than minutes, and it operates precisely by altering bicarbonate reabsorption/generation and H+ secretion, so a bicarbonate-independent, near-instant mechanism mischaracterizes the timescale and pathway. This question tests the skill of reasoning about how the renal system provides a slow metabolic offset to a chronic respiratory acid-base disturbance.', 'medium', '3B', 'Organ Systems', 'biology', 2, 90)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'reversed_relationship', 'Reverses the direction of bicarbonate handling, applying the alkalosis response to acidosis' FROM q
  UNION ALL
  SELECT id, 'C', 'misconception', 'Confuses renal compensation with respiratory CO2 clearance, assigning a lung function to the kidney' FROM q
  UNION ALL
  SELECT id, 'D', 'scale_unit_error', 'Mischaracterizes the timescale (minutes vs days) and bypasses the actual bicarbonate mechanism' FROM q;

-- Q95 [pH Control & the Bicarbonate Buffer] hard skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'pH Control & the Bicarbonate Buffer', 'During intense exercise, a runner''s skeletal muscles release large amounts of lactic acid into the blood, causing the concentration of hydrogen ions in the plasma to climb. Which sequence of events best explains how the runner''s respiratory system acts to return blood pH toward its normal set point?', '[{"label": "A", "text": "Chemoreceptors sense the rising hydrogen-ion level and decrease ventilation, retaining CO2; the added CO2 drives the equilibrium toward bicarbonate, which neutralizes hydrogen ions and raises pH"}, {"label": "B", "text": "Chemoreceptors sense the rising hydrogen-ion level and increase ventilation, expelling more CO2; the loss of CO2 drives the equilibrium toward bicarbonate and hydrogen ions, generating bicarbonate that buffers the acid"}, {"label": "C", "text": "Chemoreceptors sense the rising hydrogen-ion level and increase ventilation, expelling more CO2; the loss of CO2 pulls the carbonic-acid equilibrium toward CO2 and water, consuming hydrogen ions and raising pH"}, {"label": "D", "text": "Chemoreceptors sense the rising hydrogen-ion level and increase ventilation, which raises blood oxygen; the added oxygen directly binds the excess hydrogen ions and removes them, raising pH"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is C because the bicarbonate buffer operates on the equilibrium CO2 + H2O ⇌ H2CO3 ⇌ H+ + HCO3-. When lactic acid raises plasma H+, acid-sensing chemoreceptors drive an increase in ventilation. Blowing off CO2 lowers the CO2 term on the left, and by Le Chatelier''s principle the equilibrium shifts left (toward CO2 + H2O), which consumes free H+ and raises pH back toward the set point. (Choice C) is correct: it correctly pairs increased ventilation with CO2 loss and a leftward buffer shift that consumes H+. (Choice A) is incorrect: it reverses the ventilatory response — acidosis stimulates MORE ventilation, not less, and retaining CO2 would add H+ and lower pH further, worsening the acidosis. (Choice B) is incorrect: it gets the ventilation direction right but reverses the buffer''s response to CO2 loss — removing CO2 shifts the equilibrium left toward CO2/water (consuming H+), not right toward more H+ and bicarbonate. (Choice D) is incorrect: raising blood oxygen is not the compensation mechanism, and oxygen does not chemically bind or neutralize hydrogen ions; the correction works through the CO2/bicarbonate equilibrium, not O2. Skill: This item requires integrating chemoreceptor feedback with the direction of a coupled equilibrium shift to trace a multi-step physiological compensation.', 'hard', '3B', 'Organ Systems', 'biology', 2, 110)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'reversed_relationship', 'Reverses the ventilatory direction (decreases instead of increases ventilation) and misframes CO2 retention as pH-raising' FROM q
  UNION ALL
  SELECT id, 'B', 'process_step_confusion', 'Correct ventilation direction but reversed Le Chatelier buffer-shift direction (right instead of left on CO2 removal)' FROM q
