-- Q96 [pH Control & the Bicarbonate Buffer] hard skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'pH Control & the Bicarbonate Buffer', 'A patient in diabetic ketoacidosis accumulates ketoacids in the blood, adding a large load of H⁺ and lowering arterial pH. Assuming healthy lungs and an intact chemoreceptor response, how does the respiratory system compensate, and by what mechanism?', '[{"label": "A", "text": "Ventilation decreases, retaining CO₂ so that more bicarbonate forms and directly binds the excess H⁺"}, {"label": "B", "text": "Ventilation increases, retaining CO₂ so that the added CO₂ neutralizes the excess H⁺ in the blood"}, {"label": "C", "text": "Ventilation decreases, driving the bicarbonate buffer toward CO₂ so that H⁺ is exhaled along with the CO₂"}, {"label": "D", "text": "Ventilation increases, driving the bicarbonate buffer toward CO₂ so that exhaling CO₂ consumes H⁺ and raises pH"}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is D because the added H⁺ from ketoacids shifts the bicarbonate equilibrium (H⁺ + HCO₃⁻ ⇌ H₂CO₃ ⇌ CO₂ + H₂O) to the right, and the elevated H⁺/CO₂ stimulates chemoreceptors to increase ventilation; blowing off CO₂ pulls the equilibrium further to the right, consuming H⁺ and raising pH back toward normal. (Choice D) is correct: increased ventilation removes CO₂, which by Le Châtelier drives the buffer toward CO₂ and consumes the excess H⁺, partially correcting the low pH. (Choice A) is incorrect: decreasing ventilation retains CO₂, which shifts the equilibrium toward more H₂CO₃ and more H⁺, worsening the acidosis rather than compensating; slower breathing is the response to alkalosis, not acidosis. (Choice B) is incorrect: it pairs the correct direction (increased ventilation) with a contradictory mechanism—increased ventilation removes CO₂, it does not retain it, and adding CO₂ would generate more H⁺, not neutralize it. (Choice C) is incorrect: decreased ventilation is the wrong direction for an acid load, and H⁺ ions are not themselves exhaled; the lungs excrete acid only indirectly as CO₂ gas. This question tests the skill of reasoning from a described acid-base disturbance to the direction and mechanism of respiratory compensation.', 'hard', '3B', 'Organ Systems', 'biology', 2, 110)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'reversed_relationship', 'Reverses the compensatory direction (hypoventilation for an acid load) and misassigns the buffer shift so that CO2 retention is claimed to consume rather than generate H+' FROM q
  UNION ALL
  SELECT id, 'B', 'process_step_confusion', 'Correct ventilatory direction paired with a self-contradictory/incorrect mechanism (increased ventilation described as retaining CO2, and CO2 framed as neutralizing acid)' FROM q
