  SELECT id, 'C', 'misconception', 'Common misconception that free H+ is directly exhaled by the lungs, combined with the wrong ventilatory direction' FROM q;

-- Q97 [pH Control & the Bicarbonate Buffer] medium skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'pH Control & the Bicarbonate Buffer', 'In vigorously exercising muscle, cellular metabolism raises the local concentration of hydrogen ions and carbon dioxide in the surrounding capillary blood. Compared with hemoglobin passing through a resting tissue at the same oxygen partial pressure, how is oxygen binding by hemoglobin in the exercising tissue most directly affected?', '[{"label": "A", "text": "Hemoglobin''s affinity for oxygen decreases, so it releases more oxygen to the tissue at a given oxygen partial pressure."}, {"label": "B", "text": "Hemoglobin''s affinity for oxygen increases, so it holds oxygen more tightly and delivers less to the tissue."}, {"label": "C", "text": "Hemoglobin''s affinity for oxygen is unchanged, because only the oxygen partial pressure can alter binding."}, {"label": "D", "text": "Hemoglobin loses its ability to bind carbon dioxide, forcing all oxygen to remain bound in the capillary."}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is A because rising H+ and CO2 in metabolically active tissue lower hemoglobin''s affinity for oxygen (the Bohr effect), shifting the oxygen-hemoglobin dissociation curve rightward so that hemoglobin unloads more oxygen at any given partial pressure—precisely where working muscle needs it most. (Choice A) is correct: the added acid and CO2 stabilize the low-affinity form of hemoglobin, promoting oxygen release to the exercising tissue. (Choice B) is incorrect: increased affinity would cause hemoglobin to retain oxygen, the opposite of the Bohr effect and counterproductive during exercise. (Choice C) is incorrect: affinity is not fixed—H+ and CO2 are physiological modulators that shift the dissociation curve independently of the oxygen partial pressure. (Choice D) is incorrect: hemoglobin continues to carry CO2 (as carbaminohemoglobin), and the Bohr effect enhances rather than abolishes oxygen unloading. This question tests the skill of reasoning about how an acid/CO2 load alters gas transport by modulating hemoglobin-oxygen binding.', 'medium', '3B', 'Organ Systems', 'biology', 2, 90)
  RETURNING id
)
