-- Q98 [pH Control & the Bicarbonate Buffer] medium skill2 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'pH Control & the Bicarbonate Buffer', 'In a systemic capillary, CO2 entering a red blood cell is converted to bicarbonate, which then exits the cell into the plasma. As this bicarbonate leaves, chloride ions simultaneously move from the plasma into the red blood cell through the same membrane transporter. Which factor most directly explains why chloride enters the cell during this process?', '[{"label": "A", "text": "Chloride is actively pumped inward using ATP to drive bicarbonate against its concentration gradient out of the cell"}, {"label": "B", "text": "The transporter is an anion exchanger that must import one anion for each bicarbonate it exports, preserving electrical neutrality across the membrane"}, {"label": "C", "text": "Chloride follows bicarbonate outward to balance the charge, then re-enters by simple diffusion once equilibrium is reached"}, {"label": "D", "text": "Rising intracellular H+ produced with the bicarbonate directly attracts chloride into the cell to form hydrochloric acid"}]'::jsonb, 'B', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is B because the band 3 anion exchanger is an electroneutral antiporter: each negatively charged bicarbonate ion driven out of the cell (down the gradient created by ongoing CO2 hydration) obligatorily brings one negatively charged chloride ion in, so no net charge crosses the membrane and electroneutrality is maintained. (Choice B) is correct: the exchanger swaps one anion out for one anion in, so chloride enters specifically to replace the negative charge lost as bicarbonate exits—the essence of the chloride shift. (Choice A) is incorrect: the anion exchanger is passive and does not hydrolyze ATP; bicarbonate leaves down its own outward concentration gradient, and chloride entry is coupled to that exchange, not powered by a pump. (Choice C) is incorrect: chloride moves inward, not outward—it never leaves the cell to balance bicarbonate; reversing the direction of chloride movement contradicts the observed shift. (Choice D) is incorrect: although H+ is generated alongside bicarbonate, it is buffered by hemoglobin inside the cell and does not combine with chloride to form HCl; charge balance is achieved through anion exchange, not acid formation. The skill assessed is reasoning about how coupled membrane transport preserves electroneutrality during CO2 handling in the blood.', 'medium', '3B', 'Organ Systems', 'biology', 2, 90)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'misconception', 'Assumes coupled transport must be ATP-powered active pumping rather than passive electroneutral exchange' FROM q
  UNION ALL
  SELECT id, 'C', 'reversed_relationship', 'Reverses the direction of chloride movement (outward then back in) instead of net inward entry' FROM q
  UNION ALL
  SELECT id, 'D', 'misconception', 'Invents an H+/Cl- attraction forming HCl instead of anion-exchange charge balance' FROM q;

-- Q99 [pH Control & the Bicarbonate Buffer] hard skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Respiratory System', 'pH Control & the Bicarbonate Buffer', 'A patient hyperventilates for several minutes, blowing off large amounts of CO2, and their arterial blood becomes transiently more alkaline. Over the following hours, blood pH returns toward normal even though ventilation remains elevated. Which mechanism most directly accounts for this slower phase of pH correction?', '[{"label": "A", "text": "The lungs retain additional CO2 by reducing the ventilation rate back to baseline"}, {"label": "B", "text": "Peripheral chemoreceptors trigger an immediate increase in carbonic acid formation"}, {"label": "C", "text": "The kidneys excrete more bicarbonate into the urine, lowering plasma bicarbonate"}, {"label": "D", "text": "Hemoglobin releases stored bicarbonate directly into the plasma within seconds"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is C because the fast respiratory response (blowing off CO2) has already occurred and, with ventilation still elevated, cannot itself correct the alkalosis, so the slow, long-term compensation must come from the kidneys, which increase bicarbonate excretion to lower plasma HCO3- and pull pH back toward normal over hours to days. (Choice C) is correct: renal handling of bicarbonate is the slow (hours-to-days) arm of acid-base control; excreting excess HCO3- lowers plasma bicarbonate, which restores the HCO3-/CO2 ratio of the buffer toward normal and shifts pH back down toward baseline while ventilation is still elevated. (Choice A) is incorrect: the stem states ventilation remains elevated, so the lungs are not retaining CO2; moreover, a return to baseline ventilation would be a respiratory (fast) mechanism, not the slow phase being described. (Choice B) is incorrect: chemoreceptor-driven changes in ventilation act within seconds to minutes (the fast respiratory arm), and increasing carbonic acid formation would worsen, not correct, an ongoing loss of CO2 during continued hyperventilation. (Choice D) is incorrect: hemoglobin buffering and red-cell bicarbonate shifts occur within seconds as part of immediate chemical buffering, not the multi-hour compensation, and hemoglobin does not serve as a bicarbonate reservoir released to restore pH over hours. Skill: This item requires integrating the timescales of respiratory versus renal acid-base compensation to identify which system drives long-term pH correction.', 'hard', '3B', 'Organ Systems', 'biology', 2, 110)
  RETURNING id
)
